INSERT INTO questions (idx, dataset, example_id, prompt_id, source, subject, question_number, prompt, question, choice_a, choice_b, choice_c, choice_d, answer, gold_passage, gold_idx, generated, subtopic)
VALUES
('775', 'mbe', 'mbe_0775', 'prompt_1089', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '78', '', 'Yvette''s attorney calls Stephanie to testify that Yvette forgot her baby son at Nordstrom the last time she went shop- ping, six months ago. The prosecution objects to the testimony of Stephanie. The court should:', 'Sustain the objection, because the testimony pertains to an im- permissible character trait.', 'Sustain the objection, because it is improper opinion testimony.', 'Overrule the objection, because Stephanie has personal knowl- edge of Yvette''s character.', 'Overrule the objection, because it tends to disprove Yvette''s in- tent to commit the crime.', 'C', '', '', 0, ''),
('776', 'mbe', 'mbe_0776', 'prompt_1090', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '79', '', 'Yvette''s attorney called to the stand Lou, a cashier at Sparkle Jewelry Store, to testify as follows: two hours before she was charged with shoplifting at Nordstrom''s, Yvette had shopped at Sparkle Jewelry Store and, after paying for a $2,000 diamond ring she had pur- chased, walked out of the store leaving the diamond ring on a store counter. The prosecution objects to the testimony of Stephanie. The court should:', 'Sustain the objection, because the testimony pertains to an im- permissible character trait.', 'Sustain the objection, because it is improper opinion testimony.', 'Overrule the objection, because Lou has first hand knowledge of Yvette''s conduct in the store on the occasion in question.', 'Overrule the objection, because Lou''s testimony tends to dis- prove Yvette''s intent to com- mit the crime of shoplifting at Nordstrom''s.', 'D', '', '', 0, ''),
('777', 'mbe', 'mbe_0777', 'prompt_1091', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '80', '', 'Yvette also calls Burt, a psychologist, to testify that he had treated Yvette and, in his opinion, Yvette was suffering from a psychological condition which im- paired her memory and caused her to be forgetful. The prosecution objects to the testimony of Burt. The court should: 336 EVIDENCE', 'Sustain the objection, because the testimony pertains to an im- permissible character trait.', 'Sustain the objection, because it is improper opinion testimony.', 'Overrule the objection, if Burt is a qualified expert.', 'Overrule the objection, because Burt''s testimony is consistent with a finding of innocence.', 'D', '', '', 0, ''),
('778', 'mbe', 'mbe_0778', 'prompt_1092', 'Flemings''s Multistate Examination Workbook - Volume 2', 'evidence', '82', '', 'Mark is charged with murder. He pleads not guilty. At the request of Mark''s lawyer, the trial judge appoints Doctors Art and Cathy, psychiatrists, to examine Mark and advise Mark''s lawyer as to whether Mark should rely upon the de- fense of mental defect. At trial, Mark''s defense is diminished capacity. Mark''s lawyer calls Dr. Art, who gives an opinion in support of Mark''s defense. Mark''s lawyer rests her case. In rebut- tal, the prosecution calls Dr. Cathy, to give an opinion contrary to that of Dr. Art. Mark''s lawyer objects. The court should:', 'Sustain the objection, because of the attorney-client privilege.', 'Sustain the objection, because of the psychiatrist-patient privi- lege.', 'Overrule the objection, because as Mark''s expert medical provid- er, she is not permitted to testify adverse to Mark''s interest.', 'Overrule the objection, because Dr. Cathy was never listed as the prosecution''s expert prior to trial. EVIDENCE 337 Q 6"z Wci5 W', 'A', '', '', 0, ''),
('779', 'mbe', 'mbe_0779', 'prompt_1093', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '83', '', 'Deft is charged with the murder of Rob- ert. As part of the prosecutions''s case in chief, the prosecutor offers a certi- fied copy of Deft''s prior conviction for murdering the President. Deft objects. The evidence is:', 'Admissible, because it tends to prove Deft''s plan.', 'Admissible, because it is a mate- rial fact.', 'Inadmissible, because it is im- proper character evidence.', 'Inadmissible, because its pro- bative value is substantially outweighed by its prejudicial effect.', 'D', '', '', 0, ''),
('78', 'mbe', 'mbe_0078', 'prompt_0361', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '36', '', 'Chairco owned a commercial building, part of which it leased to Sportco. At the time the parties entered into the lease, Chairco also sold some locker room equipment (lockers and saunas) to Sportco. The bill of sale provided that: "Seller does hereby sell, convey and transfer to Buyer any right, title and interest seller may have in goods. It is expressly understood and agreed seller shall not be obligated, liable or account- able for any warranties on the goods sold to buyer." Unknown to Sportco, the equipment had been obtained from Franco, a pre- vious lessee who had been unsuccess- ful in operating his business. After Sportco purchased the equipment, Franco sued Chairco for title and pos- session of the equipment. Franco pre- vailed and repossessed the equipment from Sportco. Sportco now sues Chairco for the loss. Who prevails?', 'Sportco, because the warranty of title cannot be disclaimed.', 'Sportco, because Chairco did not specifically disclaim the war- ranty of title.', 'Chairco, because the language in the bill of sale effectively dis- claimed the implied warranty of title.', 'Chairco, provided the disclaimer of warranty was conspicuous.', 'D', '', '', 0, ''),
('780', 'mbe', 'mbe_0780', 'prompt_1094', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '85', '', 'Lucy sued Fred for injuries suffered by her when Fred collided his blue truck into her MG. At trial, Lucy calls Ricky to the stand. Ricky testifies that he was driving the MG when the accident hap- pened. He further testified that when he pulled onto the tollway, Lucy said to him, "Watch out for that blue truck - it looks like the driver has been drinking, and he can''t seem to keep control over his car." Fred''s counsel objects. The testimony is:', 'Allow the testimony, because it is trustworthy.', 'Allow the testimony, because it is relevant to the issue of whether Dave was negligent. 338 EVIDENCE', 'Inadmissible, as hearsay.', 'Inadmissible, as improper lay opinion.', 'A', '', '', 0, ''),
('781', 'mbe', 'mbe_0781', 'prompt_1095', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '86', '', 'While driving within the scope of employment for Petro Corp., Axelrod r„ noC 1,17 Aar 71-t,a 1 rn NA-a uhrd nhcF•ruPri while standing on her front lawn. After quickly dialing for an ambulance from her mobile phone, Maybel walked over to the injured Thelma, and stated, "It''s too bad that truck never slowed down.” In an action by Thelma against Petro Corp., evidence of Maybel''s statement is: At trial, the prosecution offers the tape into evidence. The tape shows Tina ancwerina nnectinnc hv nnlire nfficerc an unsteady manner. Defense counsel objects to the introduction of the tape. The court should:', 'Inadmissible, because it was not authorized by Axelrod''s employer.', 'Inadmissible, because Maybel was not under a state of excite- ment when the statement was made.', 'Admissible, because Petro Corp. ratified Axelrod''s conduct when it hired Axelrod as an employ- ee.', 'Admissible, as a present sense impression.', 'C', '', '', 0, ''),
('782', 'mbe', 'mbe_0782', 'prompt_1096', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '90', '', 'While driving home from work, George stopped at Harry''s Bar for a drink. After having a few drinks, George asked Joe, the bartender, for another. Joe, worried about George''s intoxicated state, told George that he had already had enough to drink. George then became very an- gry, and said to Joe, "Get me a drink or else." Joe again refused. 340 EVIDENCE Angered by Joe''s response, George jumped off his bar stool and hit Joe. Joe now brings suit against George to recover for his injuries. At trial, Joe''s attorney put Joe on the stand. Joe''s pro- posed testimony is that George stated to him, "Get me a drink or else." George''s attorney objects to the testimony. The court should:', 'Overrule the objection, because it is not hearsay.', 'Overrule the objection, because it is probative of the declarant''s state of mind.', 'Sustain the objection, because it is hearsay not within any excep- tion.', 'Sustain the objection, because George could not form the intent to commit a battery while intoxi- cated.', 'A', '', '', 0, ''),
('783', 'mbe', 'mbe_0783', 'prompt_1097', 'Flemings''s Multistate Examination Workbook - Volume 2', 'evidence', '91', '', 'While out on patrol, Officer Speedtrapp pulled over Burt in his new black Trans Am for speeding. He issued Burt a speeding ticket. After laying a founda- tion for admitting the radar reading, Speedtrapp testifies that he was stopped at the corner of 5th and Golden and pointed his radar gun at Burt. The gun rated Burt''s speed to be 45 m.p.h. Burt''s attorney objects to the testimony. The trial court should:', 'Not allow the testimony, because the evidentiary foundation was insufficient to establish all ele- ments of a speeding violation.', 'Not allow the testimony, because it is hearsay.', 'Allow the testimony, because radar readings are an exception to the hearsay rule.', 'Allow the testimony, because it is not hearsay.', 'C', '', '', 0, ''),
('784', 'mbe', 'mbe_0784', 'prompt_1098', 'Flemings''s Multistate Examination Workbook - Volume 2', 'evidence', '92', '', 'Tami sues Jim for fraud, alleging that a Rolls Royce that Jim sold to her was really a Bentley. In order to prove the Rolls Royce was genuine, Jim intro- duces the bill of sale he received at a car auction when he purchased the car. Tami''s counsel objects. The bill of sale is:', 'Admissible, because documents of title are conclusive of rightful ownership.', 'Admissible, because it is a party admission.', 'Inadmissible, because it is hear- say not within any exception.', 'Inadmissible, because it is not the best evidence. 341 EVIDENCE', 'D', '', '', 0, ''),
('785', 'mbe', 'mbe_0785', 'prompt_1099', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '94', '', 'John is charged with battery on Ponch, a police officer, growing out of his arrest by Ponch. John''s defense is self- defense, against excessive force used by Ponch. Through discovery proceedings, John secures the police department''s disciplinary records relating to Ponch, citizens Tom, Dick, and Harry, stating that Ponch used excessive force on each of them within six months prior to John''s incident with Ponch. John offers the records in evidence. The prosecu- tion objects. The court should rule the disciplinary reports are: Q z', 'Not allowed, because they are hearsay.', 'Allowed, because it is proper character evidence under the "victim''s exception."', 'Allowed, because of the business record exception.', 'Allowed, because the report is permissible to prove this char- acter trait of Ponch. 342 EVIDENCE m m 0', 'A', '', '', 0, ''),
('786', 'mbe', 'mbe_0786', 'prompt_1100', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '95', '', 'Laverne, the widow of Squiggy, sues Shirley in a wrongful death action, aris- ing out of Squiggy''s death in 1990. On the issue of damages, Laverne testifies that she and Squiggy had a happy and affectionate marital relationship during their entire marriage. In defense, Shir- ley seeks to introduce evidence of the fact that from 1981 to 1983, Squiggy separated from Laverne and lived with another woman. Laverne objects. The court should: The prosecution then calls Peggy to testify. Peggy testifies that six weeks earlier, when she was with a girl friend, Al and another male picked them up and offered to take them to a party, but instead drove them to a secluded area, where Al and his friend forced the women to submit to sexual intercourse. The women escaped when the men were momentarily distracted. Al objects to Peggy''s testimony. The Judge should:', 'Sustain the objection, since the it is permissible character evi- evidence is self-serving. dence.', 'Sustain the objection, because of the dead man''s statute.', 'Overrule the objection, because it is proper character evidence.', 'Overrule the objection, because the evidence is relevant.', 'B', '', '', 0, ''),
('787', 'mbe', 'mbe_0787', 'prompt_1101', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '97', '', 'Alex was fired from his job for drunken- ness and incompetency. His supervisor had warned Alex about his conduct, but was fed up when Alex failed to show up for work for three straight days. Alex retaliates by suing for back wages, claiming that his employment contract provided wages at below the mini- mum wage and set forth a "waiver" of overtime wages at any rate higher than the regular hourly rate. His employer, Andre Ristorante, disputes Alex''s al- legations as to the contractual terms. Alex intends to testify as to the alleged wage rates set forth in his employment contract with his employer. Andre''s at- torney objects. The court should:', 'Admit the testimony, because Alex has personal knowledge of the contents of the contract.', 'Admit the testimony, because it is a material issue in the action.', 'Not admit the testimony, because it is hearsay not within any ex- ception.', 'Not admit the testimony, be- cause the contract is the best evidence.', 'C', '', '', 0, ''),
('788', 'mbe', 'mbe_0788', 'prompt_1102', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '98', '', 'X is prosecuted for assault with a deadly weapon upon A. A testifies that X struck him with an iron pipe without cause. The prosecution then calls B to the stand, who testifies that he has known and lived next door to A for ten years. The prosecution then asks B: "What is the reputation as to whether A is an honest and a truthful man?" X objects. The court should:', 'Sustain the objection, because opinion evidence of a witness'' character is never allowed to at- tack or support the credibility of the witness.', 'Sustain the objection, because A''s character for truthfulness has not yet been attacked.', 'Overrule the objection, because it is relevant.', 'Overrule the objection, because it is a collateral matter.', 'D', '', '', 0, ''),
('789', 'mbe', 'mbe_0789', 'prompt_1103', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '99', '', 'Doug and Jon are arrested for robbing a jewelry store. Jon makes a plea with the district attorney to turn state''s evidence against Patty for an unrelated crime. Doug is now on trial for the robbery. William, Doug''s roommate, is the sole defense witness. Doug''s counsel calls William to the stand, to testify that Doug told him (William) that Jon alone robbed the jewelry store. The prosecu- tion objects to William''s testimony. The testimony is: 344 EVIDENCE m m C) Questions 100 - 101 are based on the following facts: Abel sues Cain for damages for personal injuries arising out of a rear-end automobile accident. While testifying, Abel produces a typewritten letter that states, "My foot slipped off the brake. Don''t worry, I will see that all your damages are paid." The letter is signed "Cain", but contains no return ad- dress. Abel is asked by his counsel if he is familiar with Cain''s signature. Abel answers, "No, but I received the letter in the mail two weeks after the accident." Abel offers the letter into evidence.', 'Admissible, as a co-conspirator party admission.', 'Admissible, because it is direct proof that Doug did not commit the robbery.', 'Inadmissible, as hearsay not within any recognized excep- tion.', 'Inadmissible, because William''s testimony is biased.', 'B', '', '', 0, ''),
('79', 'mbe', 'mbe_0079', 'prompt_0362', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '37', '', 'Joe contacted Ed''s Marina concerning the purchase of a motorboat. Joe indi- cated that he needed to use the boat at a water ski show at Marine World, and that the boat would be pulling 10 skiers at a time, at 35 miles per hour. Ed directed Joe to a used "Starcraft" boat with a 175 horsepower outboard motor. Ed stated, "This baby has a lot of power and you''ll be able to pull 20 skiers at 35 miles per hour if you de- cide to increase the size of your show." When Joe tried to pull more than 5 ski- ers, the boat could not muster more than 15 miles per hour. In addition, one week later the motor blew up. Joe contacted Ed about the problems, and was refused a refund. Joe sues Ed for breach of con- tract. What result?', 'Joe wins because Ed made an express warranty to Joe.', 'Joe wins because ofEd''s implied warranty of merchantability, which accompanied the sale to Joe.', 'Joe will lose because he should have tried out the boat before his purchase.', 'Joe will lose because the VCC does not apply to used goods. Questions 38 - 39 are based on the following facts: Bill''s Boats ("Bill''s"), a boat supply store, sent a purchase order to Marine Wholesal- ers ("Marine") on July 7. Marine wholesales boat engines and parts. The purchase order stated, "Please send immediately two Viking outboard motors at your current list price of $350 each." Marine received the order on July 9. Since Marine only had one Viking motor in stock, it shipped one Viking mot', 'D', '', '', 0, ''),
('790', 'mbe', 'mbe_0790', 'prompt_1104', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '100', '', 'Cain objects on the grounds of authen- tication. The letter is:', 'Admissible, because the contents of the letter lay the foundation for authentication.', 'Admissible, because it is direct proof that Cain was at fault.', 'Inadmissible, because Abel is not familiar with Cain''s signature.', 'Inadmissible, because the letter is self-serving.', 'C', '', '', 0, ''),
('791', 'mbe', 'mbe_0791', 'prompt_1105', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '101', '', 'Suppose that Abel overcomes the au- thenticity objection. Cain then objects on the grounds of hearsay: The letter is:', 'Admissible, because it is not- hearsay. 345 EVIDENCE Q', 'Admissible, because it is direct proof that Cain did cause the ac- cident.', 'Inadmissible, as hearsay not within any recognized excep-', 'Admissible, as hearsay that falls within a recognized exception.', 'D', '', '', 0, ''),
('792', 'mbe', 'mbe_0792', 'prompt_1106', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '102', '', 'After being admitted to the Cinema movie theater, Paul slipped on a loose piece of carpeting in the theater lobby. Paul sustained injuries to his back. At trial, Cinema calls Wendy to testify that a week before the accident Paul told her, "I cannot finish our golf game because of pains in my back." Paul objects to the testimony. The court should rule the testimony:', 'Admissible, to prove Mark did rob the 7-11 store.', 'Admissible, to prove a pertinent trait of Mark''s character.', 'Inadmissible, because character evidence may not be used to prove Mark acted in conformity therewith.', 'Inadmissible, because character evidence must be proven by reputation or opinion evidence.', 'B', '', '', 0, ''),
('793', 'mbe', 'mbe_0793', 'prompt_1107', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '104', '', 'While driving home from school, Punkey hit Brandon as he was crossing the intersection. Brandon sued Punkey for the personal injuries he sustained. At trial, Brandon testifies that imme- diately after the accident, Punkey got out of her car, raced over to Brandon, and said, "Don''t worry, I''ll pay all your medical bills." Punkey objects to Brandon''s testimony. The testimony is:', 'Admissible, because it is an ad- mission of liability. 346 EVIDENCE Q 1-1 5 mz 0 m Questions 105 - 106 are based on the following facts: Mike was a famous musician. While play- ing in a night club one night, he met Teena. The couple fell in love, were married, and started a musical career together. However, Mike has a serious drug problem, and as a result, he frequently becomes enraged when when he was unable to come up with lyrics to a new song, he "blind-sided" Thomas with his fist. Thomas was', 'Admissible, because it is an ex- cited utterance.', 'Inadmissible, because it is hear- say not within any recognized exception.', 'Inadmissible, because it is an rsff.v to bau mr.rlioal bilk', 'D', '', '', 0, ''),
('794', 'mbe', 'mbe_0794', 'prompt_1108', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '106', '', 'Assume for this question, that Mike has been arrested for cocaine traffick- ing. After Mike''s arrest, he privately spoke to Teena, saying that he was guilty, but that he would "beat the rap" and they would make many years of music together. Teena was fed up with Mike''s ways and obtained a marital dissolution. She has now been called to testify at Mike''s trial concerning Mike''s statement to her. Upon ob- jection by Mike''s attorney, the court should:', 'Exclude the evidence, because the statement was a confidential communication.', 'Admit the evidence, because the testimonial privilege terminates upon dissolution of marriage.', 'Admit the evidence, because the marital privilege is inapplicable to admissions.', 'Admit the evidence, because Teena will testify voluntarily.', 'B', '', '', 0, ''),
('795', 'mbe', 'mbe_0795', 'prompt_1109', 'Flemings''s Multistate Examination Workbook - Volume 2', 'evidence', '108', '', 'Railroad''s train was involved in a se- rious collision with Peter. As a result of that collision, Eddie, the train''s en- gineer, was slightly injured and Peter died. Peter''s heirs bring a wrongful death suit against Railroad. At trial, Railroad seeks to introduce Railroad''s accident report filed by Ed- die at the time of the accident. Eddie is no longer an employee of Railroad, and has moved to an unknown loca- tion in Mexico. Peter''s heirs object to introduction of the accident report. The report is:', 'Permit the testimony, because it was a dying declaration.', 'Permit the testimony, because it is relevant to Valerie''s state of mind.', 'Exclude the testimony, because it is hearsay.', 'Exclude the testimony, because of the dead man''s statute.', 'C', '', '', 0, ''),
('796', 'mbe', 'mbe_0796', 'prompt_1110', 'Flemings''s Multistate Examination Workbook - Volume 2', 'evidence', '110', '', 'While shopping at Vons, Bert slipped and fell on a piece of candy on the floor of an aisle. Bert sustained serious back injuries and now brings suit against Vons for his injuries.', 'Admit the testimony, because it is relevant.', 'Admit the testimony, because it is proper habit evidence.', 'Exclude the testimony, as specula- tive.', 'Exclude the testimony, as preju- dicial. END OF QUESTIONS 350 EVIDENCE EVIDENCE ANSWERS A is the correct answer. If a proper foun- dation is laid, the photograph is admis- sible into evidence. This requires that there be someone who can testify that the photograph is a true and accurate representation of the accident scene. Since anyone who was present at the scene when the photograph was taken can testify to the accuracy of the photo- graph, the photographer does not have to be present. B is in', 'C', '', '', 0, ''),
('797', 'mbe', 'mbe_0797', 'prompt_1111', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '2', '', 'Terry and Harry leased a house from Larry, the landlord. The lease was in proper form and contained the follow- ing language: "Any assignment, subletting or transfer of any rights under this lease without the express written consent of Larry, the landlord, shall be null and void and is pro- hibited." Despite this clause, after Terry and Har- ry moved into the house, Harry verbally invited Gary to share the house with Terry and himself. Gary agreed to pay his portion of the rent to Larry who did not object to this arrangement. Terry, however, objected to Gary''s sharing the dwelling, even if Gary paid a fair share of the rent.', 'The remainder to Oscar''s chil- dren and grandchildren is void because Oscar could have mar- ried a person not yet in being at the time Oscar''s will was executed.', 'Terry, because the lease contained a "no assignment" clause.', 'Harry, because Terry is not the beneficiary of the "no assign- ment" clause in the lease. "To my surviving widow for life, and then to such of my children who shall reach 30 years of age; however, if any such child should die under the age of 30 and such child shall be survived by a child or children, that child or children shall step up and take his or her parents'' share being that share which would have gone to that parent had he or she attained the age of 30 years." In 1970, at the time of th', 'Harry, because Terry''s claim is essentially a restraint on alien- ation and is disfavored.', 'C', '', '', 0, ''),
('798', 'mbe', 'mbe_0798', 'prompt_1112', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '4', '', 'In 1990, Andrea was the owner of Pinkacre. However, in 1990, Mary gave a warranty deed to Pinkacre to Nancy. Nancy promptly recorded that deed. In 1991, Andrea conveyed Pinkacre by warranty deed to Mary who promptly recorded her deed. In 1992, Mary gave a warranty deed to Pinkacre to Orene who promptly recorded her deed. Orene paid fair market value for Pinkacre and was unaware of any prior conveyances of Pinkacre. Both Orene and Nancy claim title to Pinkacre. The court should award judgment to:', 'Nancy, because her deed is prior in time to Orene''s.', 'Orene, because she was a pur- chaser for value without notice of Nancy''s claim.', 'Either Orene or Nancy, depend- ing on whether Pinkacre is lo- cated in a state which applies estoppel by deed. PROPERTY 385 LLI 0- 0ce In 1970, Orville owned Purpleacre in fee simple absolute. Unbeknownst to Orville, in 1971, Xavier entered Purpleacre under color of title and began to use a square of land on the eastern side of Purpleacre to cut fodder for food for Xavier''s sheep. After 14 years of possession of Purpleacre, Xavier gave possession of Purpleacre to Yves. Xavier also sold Yves all', 'The person who then held title to Purpleacre in fee simple ab- solute.', 'D', '', '', 0, ''),
('799', 'mbe', 'mbe_0799', 'prompt_1113', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '6', '', 'After Orville''s 1993 conveyance to Norris, title to Purpleacre was in:', 'Xavier.', 'Orville.', 'Xavier as first taker of the fod- following facts: der. In 1986, Xavier leased Purpleacre from Orville for a term of five years. At the end of the five year term, Xavier remained on Purpleacre for two more years before he quit Purpleacre. In 1993, Orville conveyed Purpleacre by quitclaim deed to Norris. Purpleacre is located in a state where the statute of limitations for adverse possession is ten years.', 'Norris. Questions 5 — 6 are based on the', 'A', '', '', 0, ''),
('8', 'mbe', 'mbe_0008', 'prompt_0035', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '66', '', 'REAL PROPERTY Question 14 Owen owned Copperacre, a large tract of mineral-rich land in a sparsely populated area. He entered into a lease with Yukon, a prospector who was interested in developing the land for mining. The term of the lease was two years and gave Yukon an option to buy the property at any time after the first year. Yukon did not record the lease. Six months later, Yukon left Copperacre for a period of time to prospect in Mexico, leaving no goods on the land that would identify him. Owen then conveyed Copperacre in fee simple to Darlene, who had inspected the property while Yukon was in Mexico and was unaware of the prior transac- tion. Darlene did not immediately record her deed. After three months in Mexico, Yukon returned to Copperacre and encountered Darlene. A statute in the jurisdiction provides, in part: No conveyance or mortgage of an interest in land, other than a lease for less than one year, is valid against any subsequent purchaser for value with- out notice thereof whose conveyance is first recorded. If Darlene brings an action to quiet title to Copperacre, how should the court rule?', 'Able only.', 'Able and Brett.', 'Brett and Carly.', 'Able, Brett, and Carly. GO ON TO THE NEXT PAGE', 'B', '', '', 0, ''),
('80', 'mbe', 'mbe_0080', 'prompt_0363', 'Flemings''s Multistate Examination Workbook - Volume 1', 'criminal', '38', '', 'Was an enforceable contract formed upon Marine''s shipment ofthe motors?', 'Yes, because Marine''s shipment constituted an acceptance.', 'Yes, because Marine acted in good faith in shipping the mo- tor.', 'No, since Marine could only ac- ceptBill''s offer by a return prom- Ise.', 'No, because Marine''s shipment of non-conforming goods was not an acceptance, but a counter-offer.', 'A', '', '', 0, ''),
('800', 'mbe', 'mbe_0800', 'prompt_1114', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '7', '', 'While her daughter, Darla, was away at school, Marie executed and promptly recorded a deed in the proper form to Marie''s property, Yellowacre, to Darla. When Marie told Dada what she (Ma- rie) had done, Darla said, "Mother, I don''t want Yellowacre. You take that deed right back. It''s yours." Before any other relevant events, Darla died leaving her entire estate to Butch. Marie then sued Butch to quiet title in Yellowacre. If Marie wins, it will be because:', 'The presumption of delivery arising from recordation is in- valid unless the grantee has knowledge of the deed at the time of recording. 386 PROPERTY Q', 'There was no effective ac- ceptance of the delivery of the deed.', 'Darla''s renunciation of Yellow- acre was a constructive convey- ance to Marie.', 'The court will impose a construc- tive trust to carry out Darla''s intent.', 'B', '', '', 0, ''),
('801', 'mbe', 'mbe_0801', 'prompt_1115', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '9', '', 'John and Joan, an unmarried couple, owned Goldacre as tenants in common. After five years, they orally agreed that there was no need for them to make wills since the survivor of either of them would own Goldacre solely and outright per this agreement. Three years later, John died intestate. One day later, Joan died, also intestate. John''s sole heir is his father, Dave; Joan''s sole heir is her aunt, Sophie. Dave claims an inter- est in Goldacre; Sophie claims all of Goldacre. Goldacre is located in a state with the Statute of Frauds, but no other applicable statute. That state does not recognize common law marriages. In the Dave v. Sophie litigation regard- ing the ownership of Goldacre, the court should find that:', 'Carl has no interest in Silver- acres.', 'Dave and Sophie each own an undivided interest in Goldacre because the Statute of Frauds applies.', 'Sophie owns Goldacres solely because John and Joan did not make wills in detrimental reli- ance on the oral agreement. PROPERTY 387', 'Sophie owns Goldacre solely be- cause she is entitled to equitable reformation of the title to reflect the oral agreement. Questions 10 —11 are based on the following facts: Orson is the owner of a 1,000 acre tract of land called Greyacres. Orson wishes to de- velop Greyacres into a planned residential community surrounding a man-made lake and marina. He needs to ensure that pro- spective purchasers of lots in Greyacres are guaranteed the following 3 things:', 'B', '', '', 0, ''),
('802', 'mbe', 'mbe_0802', 'prompt_1116', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '10', '', 'In the context of the entire scheme of de- velopment, which of the following will offer the best method of implementing Orson''s requirement that residents of Greyacres pay money to maintain the lake and marina?', 'An easement.', 'A covenant.', 'A mortgage. 388 PROPERTY Q', 'A personal contractual obligation by each purchaser.', 'B', '', '', 0, ''),
('803', 'mbe', 'mbe_0803', 'prompt_1117', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '12', '', 'Azureacre is owned by Amanda as a life tenant and Bailey as remainderman in fee simple. Amanda and Bailey were conveyed Azureacre subject to a mort- gage of $100,000, payable in $10,000 installments of the principal over ten years at ten percent interest per year payable with each installment of the principal. Azureacre produces $50,000 in net income per year after paying all expenses except the mortgage. Amanda and Bailey each dispute who should pay the mortgage principal. If Bailey seeks legal advice as to his obligations for the mortgage principal of Azureacre, he should be told:', 'He could compel Amanda to pay the mortgage principal because the income from Azureacre is more than adequate to meet this obligation.', 'Amanda could compel Bailey to pay his share of the principal because the discharge of the mortgage enhances his remain- der.', 'He could not be held person- ally liable for the mortgage, but Bailey''s remainder could be lost if the mortgage is not paid.', 'Bailey''s only protection lies in instituting an action for partition to compel the sale of Amanda''s life estate to obtain the value of his remainder. PROPERTY 389 ce 0 0 ce', 'C', '', '', 0, ''),
('804', 'mbe', 'mbe_0804', 'prompt_1118', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '14', '', 'In May, Tina moved into and began paying a monthly rental of $200 for an apartment in a ten-unit apartment building owned by Lulu. The hallways and stairwells of the building needed repair. Lulu refused to undertake those repairs, even after Tina requested she do so. Therefore, in late August, Tina met with the other tenants and discussed with them the tenants'' legal options against Lulu for failure to make repairs. When Tina paid September''s rent, Lulu notified Tina that beginning in October, Tina''s rent would be $400 per month. When Tina protested that all of the other tenants were paying $200 per month, Lulu gave Tina the statutorily-required 30-day notice to vacate the apartment. If Tina prevails in a lawsuit contesting the termination of her tenancy, the most likely reason for her victory is that:', 'Aaron, because Otto''s convey- ance created a fee simple sub- ject to executory limitation in Aaron.', 'The rent increase from $200 to $400 is unconscionable and will shock the conscience of the court. 390 PROPERTY', 'The fact that Tina would have to pay double the rental rate charged to other tenants violates the implied agreement that rent- als for similar apartments be comparable.', 'The doctrine of retaliatory evic- tion is part of the law of this jurisdiction.', 'D', '', '', 0, ''),
('805', 'mbe', 'mbe_0805', 'prompt_1119', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '16', '', '011ie owned Blackacre, a one-acre tract of land, in fee simple absolute. How- ever, Paul was in adverse possession of Blackacre. During Paul''s adverse possession, 011ie gave Agnes oral per- mission to use the south forty feet along Blackacre as a road to reach Whiteacre, a tract of Agnes'' land. During all times relevant to this question, Agnes regu- larly used Blackacre as a road to reach Whiteacre from the public highway. A few years later, Paul quit possession of Blackacre without gaining title by adverse possession. Agnes continued to use the south forty feet along Black- acre from the time of her original use for a sufficiently long period of time to gain an easement by prescription. All of this use was accomplished without further communication between Agnes and 011ie. 011ie then blocked the road on the south forty feet along Blackacre and has refused to permit Agnes'' further use. Agnes then sued to determine her continued use of the road. In that law- suit, Agnes should: Q 0 m', 'Win, because her use was ad- verse to Paul and once adversely begun, it continued in that man- ner until some affirmative show- ing of a change.', 'Win, because Agnes made no attempt to renew 011ie''s permis- sion after Paul quit possession of Blackacre. PROPERTY 391 Questions 17 —18 are based on the following facts: Two sisters, Alice and Betty, contributed one-half of the purchase price of Yellow- acres, a 50-acre tract of land. They held Yel- lowacres together as joint tenants. Five years after the original purchase, Alice proposed that the two sisters develop Yellowacres as a retail shopping center. Betty did not want to do so. She orall', 'Lose, because her use was per- missive.', 'Lose, because there is no evi- dence that she continued to adversely use Blackacre for the required period after Paul quit Blackacre.', 'C', '', '', 0, ''),
('806', 'mbe', 'mbe_0806', 'prompt_1120', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '17', '', 'In an appropriate lawsuit to determine Sam and Betty''s respective interests in Yellowacres, if Sam is adjudicated to be the owner of the western 25 acres of Yellowacres, the most likely reason for the judgment will be that:', 'Betty''s actions during Alice''s life has estopped her from asserting title to the western one-half of Yellowacres.', 'The joint tenancy was terminated by the oral agreement of Alice and Betty at the time it was made. 392 PROPERTY "CP 0 m', 'Betty had a fiduciary obligation to Sam by reason of her be- ing named executrix of Alice''s will.', 'The close blood relationship be- tween Alice and Betty removes the necessity to comply with the Statute of Frauds.', 'A', '', '', 0, ''),
('807', 'mbe', 'mbe_0807', 'prompt_1121', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '18', '', 'In an appropriate lawsuit to determine Sam and Betty''s respective interests in Yellowacres, if Betty is adjudicated to be the sole owner of Yellowacres, the most likely reason for the judgment will be that:', 'The record title of the joint ten- ancy to Yellowacres can only be changed by a duly recorded instrument.', 'The Statute of Frauds prevents the proof of Betty and Alice''s oral agreement.', 'Alice could not unilaterally sever the joint tenancy.', 'Betty''s nomination as executrix of Alice''s estate does not prevent her from asserting her claim against Sam.', 'B', '', '', 0, ''),
('808', 'mbe', 'mbe_0808', 'prompt_1122', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '19', '', 'Baker and Selwyn entered into a valid, enforceable written contract in which Baker agreed to buy and Selwyn agreed to sell Orangeacre, Selwyn''s residence. The contract contained a provision al- lowing Selwyn the right to remain in residence of Orangeacre for 30 days before relinquishing possession. The closing took place as scheduled; title passed to Baker and Selwyn remained in possession. A week later, however, the house Selwyn was scheduled to move into was destroyed. At the end of the 30-day period, Selwyn refused to leave Orangeacre. Instead, Selwyn tendered to Baker a monthly rental pay- ment in excess of the fair rental value of Orangeacre. Baker refused the rent and sued to gain immediate possession of Orangeacre. There is no law of this jurisdiction dealing with this situation and the contract is similarly silent. The landlord-tenant law of this jurisdiction requires a 30-day notice by the landlord before he can evict a tenant. Baker did not give the 30-day statutory notice. Baker''s best legal argument in support of his action for immediate possession is that Selwyn is a:', 'Licensee.', 'Tenant at sufferance.', 'Della, because she is a remote grantee — not a direct grantee of Oliver Wendell.', 'Della, because she did not re- ceive a deed containing a restric- tive covenant.', 'A', '', '', 0, ''),
('809', 'mbe', 'mbe_0809', 'prompt_1123', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '20', '', 'Assume for this question only, that Della, a purchaser from Beth, has begun construction of a multi-family apart- ment building on her lot and that Abby sues to prevent Della''s apartment build- ing. Who will prevail in this lawsuit?', 'Carol''s proposed use will allow a sufficient diversity in economic classes in the vicinity to satisfy the requirements of the Equal Protection clause of the Constitu- tion.', 'Abby, because the apartment building will lower Abby''s land value. 394 PROPERTY Q', 'There has been an insufficient showing that the common de- velopment scheme applied to the entire subdivision.', 'Restrictive equitable servitudes bind only those in privity with the original covenanting par- ties.', 'A', '', '', 0, ''),
('81', 'mbe', 'mbe_0081', 'prompt_0364', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '40', '', 'According to the facts, could Canco revoke the offer before October 1?', 'No, because Canco had given Grocer assurance that the offer would remain open.', 'No, because both parties are merchants.', 'Yes, because there was no con- sideration for keeping the offer open.', 'Yes, since Grocer relied to its detriment.', 'A', '', '', 0, ''),
('810', 'mbe', 'mbe_0810', 'prompt_1124', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '23', '', 'Maria owned three condos in Condo Heaven, numbers 6, 7 and 21. The price and fair market value of condos 6 and 7 was $50,000, and number 21, $75,000. Nellie was interested in purchasing a condo in Condo Heaven but couldn''t decide between #6 or #7. Therefore, Nellie gave Maria $50,000 and Ma- ria prepared and executed a deed to Nellie for a condo in Condo Heaven, complete in every way except that the unit number was left blank. Maria told Nellie to fill in unit #6 or #7 as she wished and then Nellie should record the deed. The next day, Nellie went to Condo Heaven, filled in unit #21 in the deed and recorded the deed. In an action by Maria to rescind the transaction, if Maria loses, the most likely reason for that judgment is that:', 'The necessity for certainty in land title records controls.', 'The agency implied to complete the deed cannot be restricted by the oral understanding. PROPERTY 395 LLI 0- 0 ce CL', 'The recordation of the deed precludes any questioning of the deed in its recorded form.', 'Maria''s casual business practices caused her loss.', 'B', '', '', 0, ''),
('811', 'mbe', 'mbe_0811', 'prompt_1125', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '24', '', 'In 1980, Harold willed Beigeacres as follows: "To my daughter, Dolly, and at her death to those of Dolly''s chil- dren who survive her, provided, however, that no such child of Dolly shall have the power to con- vey, sell or mortgage such child''s interest prior to attaining the age of 30 years; and if any such child of Dolly shall not comply with this provision then that child''s interest shall determine and pass to the remaining children of Dolly alive at that time, share and share alike." Harold''s 1980 will devised Whiteacres to his son, Solomon, in an identical manner. The residuary clause in the 1980 will gave the residual estate to Harold''s two children, Dolly and Solo- mon, equally. In 1990, Harold died sur- vived by Dolly and Solomon and their two children each. Since 1990, Dolly has had one additional child. In an action to determine the property rights in Beigeacres, it was alleged that the gifts to Harold''s grandchildren were void and that the interests in Beigeacres, after Dolly''s children''s life estates passed to Harold''s children, passed absolutely under the residuary clause of the will. Assuming a properly instituted action with all parties represented, the judge should decide that:', 'The attempted gifts to the grand- children are void as restraints on alienation.', 'The attempted gifts to the grand- children are void under the Rule Against Perpetuities.', 'The attempted gifts to the grand- children are valid except for the provisions against sale, convey- ance or mortgage.', 'The attempted gifts to the grand- children are entirely valid and will be enforced as written. 396 PROPERTY ''CP 0 m', 'C', '', '', 0, ''),
('812', 'mbe', 'mbe_0812', 'prompt_1126', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '26', '', 'In 1991, Wilma conveyed Redacres as follows: "To my friend Fred for life and then to Fred''s two children, Bar- ney and Betty, and their heirs, provided that should any of them move to California, then that child''s interest to pass to the Red Cross." In 1991, Fred was alive and had two children, Barney and Betty. In an appro- priate action to determine the interests in Redacres, the gift to Fred''s children shall be held to be:', 'An executory interest.', 'Denied, since Thelma has sole title to the property.', 'Granted, because the tenancy by the entirety that was created by the deed was destroyed when Thelma abandoned Louis.', 'Granted, because the deed never created a tenancy by the en- tirety. PROPERTY 397 Questions 27 — 28 are based on the following facts: Bernie is the owner of Blueacres, a tract of land. In 1990, he contracted to sell Blueacres to Carla. Bernie and Carla executed an agree- ment for Carla to purchase Blueacres from Bernie for $50,000 cash. Assume Blueacres is located in a jurisdiction which recognizes the principle of equitable estoppel, but has no statute specifically dealing with these problems.', 'B', '', '', 0, ''),
('813', 'mbe', 'mbe_0813', 'prompt_1127', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '28', '', 'Assume for this question only, that Carla dies before the real estate clos- ing and her will gives her real property to Ricky and her personal property to Paula. Assume further, that the contract is otherwise fully performed. Which statement is most correct?', 'Ricky has the right to specifically perform the contract.', 'Peter is entitled to the $50,000 on closing since equitable conver- sion applies here.', 'Is enforceable, because no ambi- guity appears on the face of the deed.', 'Is sufficient, if Bill paid consid- eration.', 'A', '', '', 0, ''),
('814', 'mbe', 'mbe_0814', 'prompt_1128', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '29', '', 'The legal description of the portion of Wanda''s ranch given to Bill:', 'Insufficient, because it contains no description by metes and bounds.', 'Insufficient, because the acreage given is inaccurate.', 'Insufficient, because a grantor cannot convey more than she owns.', 'Sufficient, because the discrep- ancy in area is not fatal.', 'A', '', '', 0, ''),
('815', 'mbe', 'mbe_0815', 'prompt_1129', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '31', '', 'Ethel was the fee simple owner of Weed- acres (a vacant tract of land). Weedacres was located adjacent to Hedgeacres, a tract of land with a house and barn located on it and owned in fee simple by Fred. In 1990, Ethel began digging a foundation for a building on Weedacres to be located near the property line with Hedgeacres. Ethel''s digging caused the barn and land on Hedgeacres to collapse due to earth movement. In a lawsuit by Fred against Ethel for damages to his barn and land, due to Ethel''s excava- tion, the prevailing party should be: 399 PROPERTY', 'Fred, because he has an absolute right to lateral support of his land.', 'Fred, unless the weight of the barn contributed to the damage.', 'Ethel, but only if she was negli- gent in her excavation.', 'Ethel, unless her excavation would have caused the same damage to unimproved land, or she was negligent.', 'D', '', '', 0, ''),
('816', 'mbe', 'mbe_0816', 'prompt_1130', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '32', '', 'Francisco owned Farmacres (a tract of land) in fee simple absolute. He con- veyed it "to Gilbert for life, and then to the children of Helen in fee simple." At the time of the conveyance, both Gilbert and Helen were alive; neither had any children. What interest, if any, was created in Helen''s unborn children at the time of the conveyance?', 'A vested remainder, subject to partial divestment.', 'A contingent remainder.', 'An executory interest.', 'None. Questions 33 — 34 are based on the following facts: Quintin was the owner of Sandacres (a large tract of undeveloped land) in fee simple absolute. In 1970, he subdivided Sandacres into 3 parcels, #1-3. Quintin conveyed lot #1 to Rhoda, lot #2 (the middle lot) to Susan and lot #3, he retained as vacant land for speculation. Rhoda and Susan built houses and swimming pools on their lots. The land around Sandacres was undeveloped, unim- proved and unzoned. After their houses were built, Rhoda', 'B', '', '', 0, ''),
('817', 'mbe', 'mbe_0817', 'prompt_1131', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '33', '', 'If Susan sues Rhoda to enjoin Rhoda from interfering with Susan''s contin- ued use of the common sewer line, the prevailing party will be:', 'Susan, if, and only if, she was misled by Quintin''s failure to complain when she was building her pool.', 'Rhoda, because the continued use of the common easement after a material change in circumstances would diminish the fair market value of the lots, without a cor- responding and commensurate increase in value.', 'Susan, because an incorporeal hereditament lies in grant and cannot be terminated without a writing.', 'Susan, because the termination of the necessity for the ease- ment which had been created by express grant does not affect the rights in the easement.', 'D', '', '', 0, ''),
('818', 'mbe', 'mbe_0818', 'prompt_1132', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '35', '', 'In a lawsuit by Victoria against Wilma to establish that Victoria has title to Plantacres, if Wilma loses it will be because:', 'The events of January 1, 1990 were a conditional delivery to a grantee without an escrow.', 'Wilma is a donee and not a bona fide purchaser under the record- ing act.', 'The events of January 1, 1990 were insufficient to constitute a valid delivery.', 'Wilma did not record her deed as required by the recording act.', 'C', '', '', 0, ''),
('819', 'mbe', 'mbe_0819', 'prompt_1133', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '36', '', 'In a lawsuit by Victoria against Wilma to establish that Victoria has title to Plantacres, if Victoria loses, it will be because:', 'Parol evidence is inadmissible to prove an oral condition rebutting valid delivery.', 'As between the parties to a trans- action, recording is not required to transfer title after a valid de- livery.', 'Wilma has proven that Victoria intended to part with Plantacres irrevocably.', 'This is a donative escrow, which creates consideration for the transfer through the relationship of blood or marriage. 402 PROPERTY Q', 'C', '', '', 0, ''),
('82', 'mbe', 'mbe_0082', 'prompt_0365', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '41', '', 'Grocer''s fax on September 1 had the following effect:', 'It had no legal effect because the mode of acceptance was not the same as Canco''s offer.', 'It operates as a reflection of the offer and creates a counter-offer, since Grocer changed the terms.', 'A contract for 50 cases of com was formed.', 'A contract for 50 cases of com was formed for delivery in Oc- tober and November. Questions 42 - 43 are based on the following facts: Shoe Heaven ordered 1000 pairs of children''s shoes in specified sizes and styles from Cobbler Distributing. Delivery was requested on May 1, with payment to be due 30 days from delivery. Cobbler found it could only fill the order to the extent of 900 pairs. Without communicating with Shoe Heaven, Cobbler shipped the 900 pairs of shoes. On receipt of the shoes on A', 'B', '', '', 0, ''),
('820', 'mbe', 'mbe_0820', 'prompt_1134', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '38', '', 'Yvette conveys Bambooacres (a tract of land) to Zerlina by warranty deed as a gift for Zerlina''s birthday. One year later, Yvette conveys the same property, Bambooacres, to Abelia for $100,000. Abelia is without constructive or actual knowledge of the prior deed to Zerlina. Abelia records her deed to Bamboo- acres first. Abelia receives the property pursuant to the recording act in this jurisdiction. If Zerlina sues Yvette for having lost the property to Abelia, the outcome of Zerlina''s lawsuit against Yvette will depend on:', 'Will must pay both the principal and interest.', 'Xerxes must pay both principal and interest.', 'Whether the jurisdiction views title covenants as personal or running with the land.', 'Xerxes must pay the principal and Will must pay the interest. 403 PROPERTY 0 ce a_', 'A', '', '', 0, ''),
('821', 'mbe', 'mbe_0821', 'prompt_1135', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '39', '', 'Benjy owned Bushacres (a tract of land) in fee simple absolute. He conveyed Bushacres in 1954 "to Carla and Dan, as wife and husband." In this jurisdiction, Benjy''s conveyance would be sufficient to create a tenancy by the entirety. Thereafter, Carla conveyed by a deed in valid form and delivery "my undi- vided one-half interest in Bushacres" to Esther. Carla died one year later. If Esther sues Dan to quiet title in himself and herself as co-owners of Bushacres, she will:', 'Not prevail, unless Carla and Dan were not legally married according to the laws in this jurisdiction during the relevant times in this problem.', 'Not prevail, because he is the sole owner of Bushacres. Questions 40 — 41 are based on the following facts: In 1978, Fiona owned Palmacres (a tract of land) in fee simple absolute. In that year, she executed and delivered to Gus a quitclaim deed which purported to convey to Gus all Fiona''s interest and title in Palmacres. Gus accepted the deed and placed it in his bank safe deposit box. In satisfaction of a prior debt she owed to Hal, Fiona executed and delivered a warranty deed to Hal also pur-', 'Prevail, if, and only if, Esther had no actual or constructive notice of the deed to Dan and Carla.', 'Prevail, since Esther and Dan own Bushacres as tenants in common.', 'A', '', '', 0, ''),
('822', 'mbe', 'mbe_0822', 'prompt_1136', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '40', '', 'The recording act in this jurisdiction may be: I. Race II. Race-Notice III. Notice', 'I or II.', 'II or III.', 'I or III.', 'None of the above. 404 PROPERTY Q', 'B', '', '', 0, ''),
('823', 'mbe', 'mbe_0823', 'prompt_1137', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '41', '', 'Which is the most accurate statement regarding the conflicting claims to Palmacres of Gus and Hal?', 'Valid contingent remainder.', 'Gus'' failure to record until after Hal, equitably estops Gus from asserting title against Hal (but not against Fiona).', 'The outcome will turn on wheth- er Hal paid value within the meaning of the recording act.', 'None of the above.', 'C', '', '', 0, ''),
('824', 'mbe', 'mbe_0824', 'prompt_1138', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '45', '', 'Assume for this question only, that in 1989 Max sued Oliver claiming that Max owned Pineacres and that Oliver did not. The prevailing party owning Pineacres should have been:', 'Max, because Oliver was not a bona fide purchaser for value. 406 PROPERTY', 'Max, because he was a purchaser for full market value and had no actual or constructive notice of the deed to Oliver.', 'Oliver, because Oliver had no notice of Max''s interest in Pine- acres.', 'Oliver, because Oliver''s deed was the first recorded.', 'A', '', '', 0, ''),
('825', 'mbe', 'mbe_0825', 'prompt_1139', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '47', '', 'Irene leased her house and surround- ing yard to Juan for fifteen years. The lease contained a clause prohibiting Juan from assigning his interest in the lease. Kris has approached Juan about subletting the house and yard to him. May Juan do so?', 'Yes, because restraints on alien- ation are invalid.', 'Yes, because a lease term pro- hibiting assignments is strictly construed.', 'No, because the term "assign- ment" includes "subleasing" and vice versa.', 'No, because a tenant can never assign or sublease without the landlord''s permission, since to do so would be to impair the landlord''s security interest in the property. Q -0 XI0 13 m -I -<', 'B', '', '', 0, ''),
('826', 'mbe', 'mbe_0826', 'prompt_1140', 'Flemings''s Multistate Examination Workbook - Volume 2', 'criminal', '48', '', 'Ignatz owned Grassacres (a tract of land) in fee simple absolute. He con- veyed it "to Jenny, her heirs and assigns while the property is used for ranch purposes; then to Kelly and his heirs forever. Assume the common law Rule Against Perpetuities applies to this con- veyance. Kelly''s interest in Grassacres as a result of this conveyance is best described as:', 'A possibility of reverter.', 'A right of entry (or power of Questions 49 — 51 are based on the termination). following facts:', 'An executory interest.', 'Nothing. Terah leased a single family residence from Utley for a term of four years. Without Utley''s knowledge, Terah, a skilled carpen- ter, installed three beautiful, hand-crafted floor-to-ceiling oak bookcases, which he se- curely bolted to the wall next to the fireplace. He also replaced the old wooden steps lead- ing to the front door with a new, larger and more efficient set of stone steps and he added a banister. At the end of his lease, Terah re- moved the bookcases, leaving several deep', 'D', '', '', 0, ''),
('827', 'mbe', 'mbe_0827', 'prompt_1141', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '49', '', 'In an action for damages to the house brought by Utley against Terah for the removal of the bookcases, the prevail- ing party will be:', 'Terah, but only if the bookcases were used in his trade or busi- ness.', 'Terah, but only if the jurisdiction follows the modern trend in the law of fixtures.', 'Terah, because the bookcases are considered personal property.', 'Utley, because the bookcases are considered real property.', 'D', '', '', 0, ''),
('828', 'mbe', 'mbe_0828', 'prompt_1142', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '50', '', 'In an action by Terah against Utley to recover the cost of replacing the old front door steps, Terah will: 408 PROPERTY Q', 'Win, because he has created an improvement to Utley''s freehold interest in the property.', 'Win, but only if he added value of the improvement will last be- yond the term of Terah''s lease.', 'Lose, if the jurisdiction preserves the common law doctrine of per- missive waste.', 'Lose, if the jurisdiction preserves the common law doctrine of ameliorative waste.', 'D', '', '', 0, ''),
('829', 'mbe', 'mbe_0829', 'prompt_1143', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '53', '', 'In 1969, UNICEF''s interest in Gras- sacres could have best been described as:', 'A valid contingent remainder.', 'An invalid contingent remain- der.', 'A valid executory interest.', 'An invalid executory interest.', 'D', '', '', 0, ''),
('83', 'mbe', 'mbe_0083', 'prompt_0366', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '42', '', 'Assuming that Cobbler is now suing Shoe Heaven for breach of contract, which ofthe following is the most likely outcome?', 'Judgment will be for Cobbler because he substantially per- formed.', 'Judgment will be for Cobbler, but Shoe Heaven will be entitled to set off any damages attribut- able to the non-delivery of the 100 pairs of shoes.', 'Judgment will be for Shoe Heaven because Cobbler had not filled the order according to its specified terms.', 'Judgment will be for Shoe Heaven, but only because a 10% deficiency in the amount deliv- ered would be considered a sub- stantial failure of performance. CONTRACTS iii', 'C', '', '', 0, ''),
('830', 'mbe', 'mbe_0830', 'prompt_1144', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '54', '', 'Yetta was the fee simple owner of Wheatacres, a tract of land planted with a yearly, seasonal wheat crop. Yetta reached agreement with her neighbor, Zedidiah, that in exchange for an an- nual payment of $1000, after Yetta had harvested her wheat crop, Zedidiah had the privilege to take and use the leftover wheat from Yetta''s fields to feed his animals. That arrangement was formal- ized in a written document, duly signed and recorded. By its terms, Zedidiah''s privilege was exclusive against all others except Yetta, who reserved the right to use Wheatacres for any purpose whatsoever, including harvesting all the wheat from her fields. Two years later, the state condemned Wheatacres by eminent domain for use as a municipal golf course. In an action by Zedidiah against the state for a portion of the condemnation award for Wheatacres, Zedidiah will: Questions 52 — 53 are based on the', 'Win, because he has a profit a prendre, which is a property right protected by the due process clause of the federal Constitu- tion.', 'Win, because he has a license, which is a property right pro- tected by the due process clause of the federal Constitution.', 'Lose, because he has a profit a prendre, which is not a prop- erty right protected by the due process clause of the federal Constitution. Questions 55 — 58 are based on the following facts: Adam is the fee simple owner of Oakacres (a tract of land) located next to the Elmacres, a tract of land which he also owned in fee simple. In 1980, Adam deeded Elmacres to Boris in return for a promise in that same document that Boris would not construct anything other than a single-family dwelling on Elmacr', 'Lose, because he has a license, which is not a property right pro- tected by the due process clause of the federal Constitution.', 'A', '', '', 0, ''),
('831', 'mbe', 'mbe_0831', 'prompt_1145', 'Flemings''s Multistate Examination Workbook - Volume 2', 'constitutional', '55', '', 'Assume for this question only, that in 1984, Boris built a multiple-family apartment house on Elmacres. In a lawsuit for $40,000 (damages to com- pensate Adam for the fact that Boris did not honor the 1980 agreement), Adam should:', 'Win, because Boris broke the 1980 promise.', 'Win, but only if the burden of the covenant touches and concerns land.', 'Win, but only if the benefit of the covenant touches and concerns land.', 'Win, but only if the benefit and the burden of the covenant touch and concern land. PROPERTY 411 Q', 'A', '', '', 0, ''),
('832', 'mbe', 'mbe_0832', 'prompt_1146', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '56', '', 'Assume for this question only, that in 1988, Boris built a multiple-family apartment house on Elmacres. In a lawsuit for $40,000 (damages to com- pensate Carole for the fact that Boris did not honor the 1980 agreement), Carole should:', 'Lose, even though Boris broke the 1980 promise.', 'Win, but only if the burden of the covenant runs with the land.', 'Win, but only if the benefit of the covenant runs with the land.', 'Win, but only if the benefit and the burden of the covenant run with the land.', 'C', '', '', 0, ''),
('833', 'mbe', 'mbe_0833', 'prompt_1147', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '58', '', 'Assume for this question only, that the 1980 promise by Boris to Adam was not made in the Adam-Boris deed, but made in a written, notarized document executed, delivered and recorded one month later for which Adam paid Boris $1,000. Assume further that in 1991, Della built a multiple-family apartment house on Elmacres. In a lawsuit for $40,000 (damages to compensate Car- ole for the fact that Della did not honor the 1980 agreement), Carole should:', 'Win, because Della broke the 1980 promise.', 'Win, but only if the benefit and the burden of the covenant touch and concern land.', 'Lose, because Adam and Boris are not in horizontal privity with each other.', 'Lose, but only if the surround- ing properties were zoned for multi-family dwellings so as to make Della''s restriction an eco- nomically inefficient use of the land. 412 PROPERTY Q', 'C', '', '', 0, ''),
('834', 'mbe', 'mbe_0834', 'prompt_1148', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '59', '', 'Ginny is the fee simple owner of Strawacres (a tract of land). In 1980, Ginny built a house on Strawacres and began occupying the property. In 1992, because she had never had a place to park her car before, Ginny built a garage on Strawacres. In 1991, she conveyed the mineral rights to the land beneath Strawacres to Horace, who immediately began mining the minerals. Horace enlarged his mining operations under Strawacres, in 1993, until his exca- vation caused subsidence damage to Ginny''s house and garage. In a lawsuit by Ginny against Horace for subsidence damage to her house and garage on Strawacres, if Ginny cannot prove that Horace negligently excavated beneath Strawacres, she will recover:', 'Nothing.', 'Damages for the house, but not for the garage.', 'Damages for the garage, but not for the house.', 'Damages for the house and ga- rage.', 'B', '', '', 0, ''),
('835', 'mbe', 'mbe_0835', 'prompt_1149', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '61', '', 'In 1990, after Benny''s death, the title to the property is held:', 'By Carl only.', 'By Della only.', 'By Carl and Della as joint ten- ants.', 'By Carl and Della as tenants in common.', 'D', '', '', 0, ''),
('836', 'mbe', 'mbe_0836', 'prompt_1150', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '62', '', 'Assume for this question only, that Carl and Della are tenants in common. In 1993, if Della sues Carl for an ac- counting as a result of that action, Della will:', 'Owe 1/2 of the property taxes paid by Carl, but receive an offset for the fair market rental value of Carl''s use of the prop- erty.', 'Owe 1/2 of the property taxes paid by Carl, but not receive an offset for the fair market rental value of Carl''s use of the prop- erty.', 'Not owe 1/2 of the property taxes paid by Carl, but receive an offset for the fair market rental value of Carl''s use of the property.', 'Not owe 1/2 of the property taxes paid by Carl, and not receive an offset for the fair market rental value of Carl''s use of the prop- erty.', 'B', '', '', 0, ''),
('837', 'mbe', 'mbe_0837', 'prompt_1151', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '63', '', 'Ellen was the owner of Whiteacre, a tract of land which she owned in fee simple absolute. In 1950, Ellen con- veyed Whiteacre as follows: "to Fran- cisco for life, and then to Francisco''s children for life, and then to Francisco''s grandchildren." In 1950, Francisco was 40-years-old and had two living chil- dren, Guadalupe and Hortensia, but no grandchildren. In 1952, another daugh- ter of Francisco, Isabella was born, but Isabella only lived until 1982. Which of Francisco''s grandchildren may receive an interest under Ellen''s 1950 convey- ance?', 'The children, if any, of Guada- lupe, Hortensia and Isabella, since the "all or nothing" rule applies.', 'The children, if any, of Guada- lupe and Hortensia, but not Isa- bella, since Isabella was born af- ter the date of the conveyance. 414 PROPERTY 0 m -0 -4', 'The children, if any, of Isabella only, since in a per stirpes dis- tribution, each child will receive his or her deceased parent''s share.', 'None, since the "all or nothing" rule applies.', 'D', '', '', 0, ''),
('838', 'mbe', 'mbe_0838', 'prompt_1152', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '65', '', 'Larry is the fee simple absolute owner of Greenacre, a tract of land with a house located in the state of Columbia. In 1980, Larry was 18 and lived with his parents in the state of Marbury, 100 miles away from Greenacre. In 1980, Maxella moved into the house on Greenacre, planted a vegetable garden, paid all taxes and assessments on Greenacre, and received mail and telephone service at that address. In 1982, Larry suffered a traumatic injury, became insane and was committed to a psychiatric hospital. The age of major- ity in Columbia is 21. Assuming that Columbia follows the common law of real property, when, if ever, does Max- ella gain title to Greenacre?', 'The year 2000.', 'The year 2003.', 'The Rule in Dumpor''s case re- quires the landlord to accept this assignment.', 'The Rule in Spencer''s case re- quires the landlord to accept this assignment.', 'B', '', '', 0, ''),
('839', 'mbe', 'mbe_0839', 'prompt_1153', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '66', '', 'Assume for this question only, that Laurette refused to accept Tomasso as a tenant and accepted no money from him. If Tomasso sues Laurette to force her to accept him as a tenant, Tomasso''s best argument would be that:', 'Lease covenants are strictly con- strued against the landlord.', 'A covenant prohibiting assign- ments does not prohibit sub- leases, and vice versa. 416 PROPERTY Q', 'The benefit of the covenant does not increase or enhance the value of the land or the landlord''s es- tate therein.', 'The burden of the covenant does not curtail the use of the land or diminish the value of the tenant''s estate therein.', 'C', '', '', 0, ''),
('84', 'mbe', 'mbe_0084', 'prompt_0367', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '43', '', 'Assume for this question only, that Shoe Heaven accepted the shipment of 900 pairs of shoes and gave notice to Cob- bler that the shipment was incomplete. Upon receiving no reply, Shoe Heaven brought suit against Cobbler for dam- ages caused by Cobbler''s failure to de- liver the remaining 100 pairs of shoes. Which of the following is the most likely outcome?', 'Shoe Heaven will recover dam- ages against Cobbler.', 'Shoe Heaven will recover, but only if Cobbler''s failure to de- liver the remaining 100 pairs of shoes could be considered a ma- terial breach.', 'Shoe Heaven will not recover because it waived Cobbler''s breach by accepting the 900 pairs of shoes.', 'Shoe Heaven will not recover because Cobbler shipped the shoes it had. m CONTRACTS', 'C', '', '', 0, ''),
('840', 'mbe', 'mbe_0840', 'prompt_1154', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '68', '', 'Assume for this question only, that Laurette accepted Tomasso as an as- signee, but that Tomasso never moved in. Assume further, that neither Tina nor Tomasso ever paid rent. At the end of the lease term, Laurette may collect:', '$3000 from Tomasso, under privity of contract.', '$3000 from Tomasso, under privity of estate.', '$4800 from Tina, under privity of contract.', '$1800 from Tina, under privity of estate.', 'D', '', '', 0, ''),
('841', 'mbe', 'mbe_0841', 'prompt_1155', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '70', '', 'Assume for this question only, that Albert sues Owen in a timely manner for breach of the covenant of seisin. If Albert prevails, his damages will be:', '$20,000.', '$25,000.', '$40,000.', '$50,000.', 'B', '', '', 0, ''),
('842', 'mbe', 'mbe_0842', 'prompt_1156', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '72', '', 'Assume for this question only, that Albert remained unaware of Owen''s tenancy in common interest in Redacres with Lee. Albert then sold Redacres by warranty deed for $50,000 to Bea. After Bea paid the money to Albert and ac- cepted the deed, Lee sued Bea to quiet title in himself as a tenant in common in Redacres with Bea. If Bea then sues Albert for breach of one of the cov- enants for title in the Albert-Bea deed, Bea will recover:', '$15,000.', '$20,000.', '$25,000.', '$40,000.', 'B', '', '', 0, ''),
('843', 'mbe', 'mbe_0843', 'prompt_1157', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '71', '', 'Assume for this question only, that Al- bert purchased a title insurance policy for $50,000 on the property, but that the title insurance company did not disclose to Albert the fact that Owen only owned a tenancy in common interest in Red- acres. That fact was discovered by the title insurance company during its title search. If Albert sues the title insurance company and prevails, his damages will be:', '$20,000.', '$25,000.', '$40,000.', '$50,000.', 'B', '', '', 0, ''),
('844', 'mbe', 'mbe_0844', 'prompt_1158', 'Flemings''s Multistate Examination Workbook - Volume 2', 'contracts', '73', '', 'Assume the same facts as in question 72, except that the deed from Albert to Bea was a quitclaim deed. If Bea sues Owen for breach of one of the title covenants, her damages will be:', '$0, she received a quitclaim deed.', '$20,000. 418 PROPERTY 0 ''CP m', '$25,000.', '$40,000.', 'B', '', '', 0, ''),
('845', 'mbe', 'mbe_0845', 'prompt_1159', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '76', '', 'Wilbur owns a one-acre tract of land in the state of Jefferson. That land was located five miles away from the near- est source of fresh water, the Jefferson River. If Wilbur wants to transport water from the Jefferson River to use to irrigate his crops, which system of water rights for the state of Jefferson will best allow him to do so? I. Natural Flow Riparian Rights. II. Reasonable Use Riparian Rights.', 'The year 1969.', 'The year 1971.', 'The year 1986.', 'Never.', 'C', '', '', 0, ''),
('846', 'mbe', 'mbe_0846', 'prompt_1160', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '75', '', 'Assume the same facts as in question 74, except that Sara moved onto Pur- pleacres in 1949. Assuming that the state of Madison follows the common law of real property, when, if ever, does Sara become the owner of Pur- pleacres? III. Prior Appropriation Rights.', 'The year 1969.', 'The year 1971.', 'The year 1986. PROPERTY 419', 'None of the above.', 'A', '', '', 0, ''),
('847', 'mbe', 'mbe_0847', 'prompt_1161', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '77', '', 'Sam orally agreed to sell Orangeacre to Beth for $100,000. That agreement was reduced to a writing, which complied with all the formalities for the statute of frauds. It stated that Sam would transfer by marketable title via a warranty deed a fee simple absolute in Orangeacre to Beth on July 1. Sam contracted in writ- ing for Theresa to sign that Sam-Beth agreement as Sam''s agent. Beth orally arranged to have Carlos sign that same agreement for Beth as her agent. The agreement described above was signed by "Theresa as agent for Sam, the seller "and by Carlos, "as agent for Beth, the buyer." Beth later refused to complete the purchase of Orangeacre. If Sam sues Beth, and Beth pleads the statute of frauds as a defense, Sam will:', 'Win, because the land sales con- tract was in writing.', 'Win, because the Sam-Theresa contract was in writing.', 'Lose, because the Beth-Carlos contract was not in writing.', 'Lose, because the land sales con- tract was not personally signed by the parties to be charged. Questions 78 — 79 are based on the following facts: In 1930, Lee, the fee simple absolute owner, conveyed Violetacres "to Harry for life, then to Lee''s heirs." In 1940, Mark, the fee simple absolute owner, conveyed Indigoacres "to Harry as long as California requires attorneys to pass the California Bar Examination." In 1950, Nell, the fee simple absolute owner, conveyed Purpleacres "to Harry forever.', 'C', '', '', 0, ''),
('848', 'mbe', 'mbe_0848', 'prompt_1162', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '78', '', 'If Wendy sues to claim her dower interest in Harry''s property, in which property(s) will she receive an inter- est? I. Violetacres. II. Indigoacres. III. Purpleacres.', 'I, II and III.', 'I and II only.', 'II and III only.', 'Neither I, II nor III.', 'C', '', '', 0, ''),
('849', 'mbe', 'mbe_0849', 'prompt_1163', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '79', '', 'If Wendy sues to receive her dower interest in Harry''s real property, the interest she will receive is: 420 PROPERTY', 'A fee simple absolute in all seised lands.', 'A life estate in all seised lands.', 'A 1/2 interest in all seised lands.', 'A 1/3 interest in all seised lands.', 'D', '', '', 0, ''),
('85', 'mbe', 'mbe_0085', 'prompt_0368', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '44', '', 'Liz, owner of Fabco, and Sally, man- ager ofSilk Creations, had a phone con- versation, during which an agreement was reached that Sally would buy 500 yards of silk at $10 per yard from Liz. Liz then sent a signed letter to Sally to confIrm the transaction. The letter omit- ted the price term. A month later, Liz called to confirm the date of delivery, but was told by Sally that she did not need the order. Assuming that Liz sues Sally for a breach of contract, what is the most likely outcome?', 'There will be judgment for Sally because the written confirmation was not signed by the party to be charged.', 'There will be judgment for Sally because the confirmation was insufficient since the price was omitted.', 'There will be judgment for Sally because Liz did not verify the order with Sally within 10 days of sending the confirmation.', 'There will be judgment for Liz because both parties are mer- chants.', 'A', '', '', 0, ''),
('850', 'mbe', 'mbe_0850', 'prompt_1164', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '81', '', 'In 1950, after the conveyance of Scarle- tacre to Agnes, what is the interest that Lee has in that property?', 'A possibility of reverter.', 'A right of entry.', 'A reversion.', 'None of the above.', 'C', '', '', 0, ''),
('851', 'mbe', 'mbe_0851', 'prompt_1165', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '82', '', 'In 1965, after Agnes'' conveyance to Bruno, what is the interest that Bruno has in Scarletacre?', 'A life estate.', 'A fee simple absolute.', 'A remainder after Bruno''s life estate.', 'A fee tail.', 'A', '', '', 0, ''),
('852', 'mbe', 'mbe_0852', 'prompt_1166', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '84', '', 'In 1980, after Agnes'' death, what is the interest that Lee has in Scarletacre?', 'A possibility of reverter.', 'A right of entry.', 'A reversion.', 'None of the above.', 'C', '', '', 0, ''),
('853', 'mbe', 'mbe_0853', 'prompt_1167', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '83', '', 'In 1980, after Agnes'' death, what is the interest that Carlotta has in Scarleta- cre?', 'Natural flow riparian rights theory only.', 'Reasonable use riparian rights theory only. 422 PROPERTY Q', 'Either natural flow riparian rights theory or reasonable use riparian rights theory.', 'None of the above.', 'D', '', '', 0, ''),
('854', 'mbe', 'mbe_0854', 'prompt_1168', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '86', '', 'The state of Jackson has a zoning or- dinance which classifies property uses into four types: single-family residen- tial; multi-family residential; com- mercial; and industrial. Single-family residential is considered the highest use of a property, next multi-family, then commercial, and industrial is the lowest use. Jackson''s zoning ordinances are cumulative. Which uses are permitted in the multi-family residential zone? I. Single-family residen- tial. II. Multi-family residen- tial. III.Commercial. IV. Industrial.', 'I and IV only.', 'II only.', 'I and II only.', 'II, III and IV only. Questions 87 — 89 are based on the following facts: In 1960, Juan was the fee simple owner of Taupeacres, a tract of land with a house on it. In 1961, the telephone company requested and received a written agreement from Juan giving the company the right to install and maintain telephone poles and wires across Taupeacres. The telephone company did in fact install poles and wires across Tau- peacres.', 'C', '', '', 0, ''),
('855', 'mbe', 'mbe_0855', 'prompt_1169', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '87', '', 'If in 1972 Juan sues to remove the telephone wires from Taupeacres and he loses, it will probably be because:', 'The telephone company has a license.', 'The telephone company has an easement.', 'The telephone company has gained title to Taupeacres by prescription.', 'The telephone company has an easement by necessity, since phone service is necessary in today''s society.', 'B', '', '', 0, ''),
('856', 'mbe', 'mbe_0856', 'prompt_1170', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '88', '', 'Assume for this question only, that in 1975 the telephone company permitted a cable television company to place its cables on the telephone company''s poles which crossed Taupeacres. If Juan sues to prevent the cable company''s use of his land, Juan''s best argument will be: PROPERTY 423 Q', 'The telephone company has a non-exclusive easement.', 'The telephone company has an exclusive easement.', 'The telephone company has an easement in gross.', 'The telephone company has an easement by prescription.', 'A', '', '', 0, ''),
('857', 'mbe', 'mbe_0857', 'prompt_1171', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '90', '', 'In 1994, the school board seeks to quiet title to Magentaacres in itself. A court will most likely quiet title to the prop- erty in:', 'The school board, in fee simple absolute.', 'The school board, but only until Chad retakes the property.', 'Chad, in fee simple absolute.', 'Chad, but only if it is not eco- nomically efficient to continue to use Magentaacres as a school.', 'A', '', '', 0, ''),
('858', 'mbe', 'mbe_0858', 'prompt_1172', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '91', '', 'For which interest in land should Chad''s lawyer argue, in order to retain for Chad the greatest possible rights in Magenta- acres, as a result of this conveyance?', 'A right of entry. 424 PROPERTY Q', 'A power of termination.', 'A possibility of reverter.', 'A reversion. Questions 92 — 93 are based on the following facts: Louisa leased an apartment to Tilly for twenty-four months, beginning January 1, 1991. The lease was in writing and provided for an annual rental of $4,800, payable in 12 monthly installments. On January 1, 1991, Louisa handed the keys to the apartment to Tilly. However, the previous tenant, Tom, was still in possession of the apartment.', 'C', '', '', 0, ''),
('859', 'mbe', 'mbe_0859', 'prompt_1173', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '92', '', 'The type of tenancy created in Tilly by the lease agreement was a:', 'Periodic tenancy, whose term is month-to-month because of the monthly rental installments.', 'Periodic tenancy, whose term is year-to-year because the lease states an annual rental term of $4,800.', 'Tenancy at will, which is turned into a periodic tenancy by the acceptance of rent.', 'Tenancy for years, because a definite ending date is provided in the lease.', 'D', '', '', 0, ''),
('86', 'mbe', 'mbe_0086', 'prompt_0369', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '46', '', 'Smith, a commercial real estate broker, traveled quite frequently in order to consummate real estate sales. Late one night, while returning home to Califor- nia from a business trip, in which Smith had sold a $2.1 billion dollar commer- cial building, he left his brief case in the baggage claim area at the airport. The next morning, Smith realized that he had left his brief case at the airport. He phoned the airport to see if anyone had turned in his brief case, but the se- curity desk told Smith nobody had turned his brief case in to "Lost and Found." Smith, desperate to get his brief case back, since it had all the legal pa- pers from his $2.1 billion dollar sale, posted flyers all around the airport. The flyers stated: "Lost - one black brief case, contains the name ''Smith.'' Will pay $500.00 to anyone for its return. Call (213) 555-2645." Early that evening, Ethel, who had just arrived to California, read the flyer posted in the arriving area while she was waiting, for some friends to pick her up. After an hour of waiting, she went to the baggage claim area to claim her lug- gage. Her friends were in the baggage area waiting her arrival. Ethel, retrieved all her bags and noticed the black brief case described on the flyer on the lug- gage carousel. She picked up the brief case, tore a lost flyer off the wall and left the airport with her friends. CONTRACTS iii A few days later, Smith realized that he had put those legal papers in his suit- case. Since he had found the papers and the brief case was worth less than $500.00, he decided that he did not need the return of the brief case. As Smith was on his way out the door to go to the airport to take down the posted fly- ers, Ethel called regarding the briefcase that she had found. She asked Smith, "Did you lose a black brief case at the airport?" Before anything else was said by Ethel, Smith replied, "I thought I had left important legal papers in the brief case that I was working on, but I''ve found the papers." He', 'Recover, because a contract was formed when she called Smith to return his brief case.', 'Recover, because Smith created a unilateral contract upon the posting of the flyers, and once Ethel performed, it became irre- vocable.', 'Not recover, because no contract was formed.', 'Not recover, unless she returns the brief case. &I CONTRACTS Questions 47 - 48 are based on the following facts: On September 1, X wrote a letter to Y, an acquaintance of his, stating, "I''m in need of a truck for transportation for my business and will buy your ''YO'' truck for $10,000, upon you bringing it to my office at 1313 Capitol Street in Anaheim, on or before Sep- tember 6." On September 3, Y received the letter and immediately replied by mail, "I accept your offer and promise to deliver t', 'C', '', '', 0, ''),
('860', 'mbe', 'mbe_0860', 'prompt_1174', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '93', '', 'If Tilly sues Louisa claiming a violation of the landlord''s duties towards a ten- ant because of the continued presence of Tom in the apartment, Tilly, under modern law, should:', 'Win, because Tilly is entitled to actual possession of the estate promised by Louisa. PROPERTY 425 LLI CL 0', 'Win, because Louisa''s lease with Tilly is an election by the landlord to treat Tom''s tenancy at sufferance as a trespass.', 'Lose, because Tilly, as the owner of the non-freehold estate, is entitled to possession of the apartment and therefore is the only one entitled to sue Tom in ejectment.', 'Lose, because Louisa has fully delivered the legal right to pos- session to Tilly. Questions 94 — 95 are based on the following facts: In 1960, Bo owned twenty acres with a house on the south 1/2 of the property. Bo cleared a dirt road from the house to the only public road which ran along the north frontage of the property. In 1970, Bo gave, by warranty deed, the north 1/2 of the property to Celia and kept for himself the south 1/2 with the house. Bo continued to use the dirt road to reach the', 'A', '', '', 0, ''),
('861', 'mbe', 'mbe_0861', 'prompt_1175', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '94', '', 'In 1989, if Bo is able to use the dirt road access Celia''s property over her objections, it is because he has an: I. Easement by Implica- tion/Quasi-Easement. II. Easement by Necessity. III. Easement by Prescrip- tion.', 'I and II only.', 'II and III only.', 'I and III only.', 'I, II and III.', 'A', '', '', 0, ''),
('862', 'mbe', 'mbe_0862', 'prompt_1176', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '95', '', 'Assume for this question only, that in 1988 the county put in a new road along the southern frontage of Bo''s property. If Celia seeks to prevent Bo from using the dirt road across Celia''s property, Bo''s strongest argument in opposition will be that he (Bo) has: 426 PROPERTY', 'An easement by prescription.', 'An easement by implication/ Quasi-easement.', 'An easement by necessity.', 'A license. Questions 96 — 99 are based on the following facts: 0 "CP Minny and Nora are owners of adjoining land. In 1970, Minny promises Nora that Minny will maintain her land forever, as a single-family residence, only. That promise was made in writing and was recorded with the county recorders office. In 1975, Nora conveyed her property to Peter, who did not have actual knowledge of the promise.', 'B', '', '', 0, ''),
('863', 'mbe', 'mbe_0863', 'prompt_1177', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '96', '', 'Assume for this question only, that in 1980 Minny develops her land as a multiple-family apartment complex. If Peter sues Minny for damages for breaching the 1970 Minny-Nora prom- ise, Peter will:', 'Win, because the covenant runs with the land.', 'Lose, because there is no vertical privity.', 'Lose, because there is no hori- zontal privity.', 'Lose, because the covenant does not touch and concern land.', 'A', '', '', 0, ''),
('864', 'mbe', 'mbe_0864', 'prompt_1178', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '97', '', 'Assume for this question only, that in 1976 Minny conveys her property to Otto, who does not have actual knowl- edge of the promise. In 1980, Otto develops his land as a multiple-family apartment complex. If Peter sues Otto for damages for breaching the 1970 Minny-Nora promise, Peter will: PROPERTY 427', 'Win, because the covenant runs with the land.', 'Lose, because there is no vertical privity.', 'Lose, because there is no hori- zontal privity.', 'Lose, because the covenant does not touch and concern land.', 'C', '', '', 0, ''),
('865', 'mbe', 'mbe_0865', 'prompt_1179', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '98', '', 'Assume for this question only, that in 1976 Minny conveys her prop- erty to Otto, who does not have actual knowledge of the promise. In 1980, Otto wishes to develop his land as a multiple-family apartment complex. If Peter sues Otto to specifically enforce the 1970 Minny-Nora promise against Otto, Peter will:', 'Win, but only if Minny and Nora had an interest in the same land at the same time in 1970.', 'Win, but only if the character of the land was such to make Otto aware of the single-family restriction.', 'Lose, because there is no vertical privity.', 'Lose, but only if the notice was insufficient. 428 PROPERTY', 'D', '', '', 0, ''),
('866', 'mbe', 'mbe_0866', 'prompt_1180', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '100', '', 'Larry leased Brownacres to Tilly for a period of three years beginning November 1, 1990. On November 5, 1993, Tilly was still in possession of Brownacres without obtaining Larry''s prior consent to her continued presence on the property. As of that date, she has not paid Larry any money for her pos- session of Brownacres after October 31, 1993. Before Larry decides what legal action to take with respect to Tilly''s continued presence on Browna- cres, she may best be describe as a:', 'Periodic tenant.', 'Tenant for years.', 'Tenant at sufferance.', 'Trespasser.', 'C', '', '', 0, ''),
('867', 'mbe', 'mbe_0867', 'prompt_1181', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '102', '', 'Bernice agreed in writing to buy Sarah''s land. Since Bernice did not have enough cash to pay the purchase price immediately, they entered into the following land security device agreement. Their agreement stated that Bernice would pay Sarah a monthly percentage of the total purchase price plus interest each month until the total price and accrued interest was paid. Bernice had the legal right to posses- sion of the property and the obligation to pay taxes, etc. on it. As security for the money owed, Sarah would transfer legal title to Bernice when the total price was paid. If at any time Bernice defaulted on her payments, Sarah could cancel the agreement, retain all moneys paid, and retake possession. This land security device is most prop- erly described as: Q 0 m 7C1', 'A deed of trust.', 'An installment land contract.', 'A mortgage.', 'A present transfer of a leasehold coupled with a future interest in fee simple absolute when Bernice pays the full purchase price. 429 PROPERTY', 'B', '', '', 0, ''),
('868', 'mbe', 'mbe_0868', 'prompt_1182', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '103', '', 'Aaron borrowed $100,000 from Barry to purchase Blackacre. In return, he gave Barry a mortgage on Blackacre for 30 years. After 15 years, Aaron sold Blackacre to Carla who began paying the mortgage debt to Barry. However, after 5 years of payments, Carla moved from Blackacre and stopped paying rent. Which of the fol- lowing people are personally liable on the mortgage to Barry?', 'Aaron.', 'Carla.', 'Aaron and Carla.', 'Neither Aaron nor Carla.', 'A', '', '', 0, ''),
('869', 'mbe', 'mbe_0869', 'prompt_1183', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '105', '', 'Gayle sold Blueacre to Hector, who gave her a 30 year mortgage as security for the purchase price. Fifteen years later, Hector sold Blueacre to Ignatz, who assumed the mortgage. Ignatz defaulted and Blueacre was sold at a judicial sale for less than the remaining debt. From whom can Gayle collect the deficiency on the debt?', 'Ellen. If a transfer is silent, it is presumed to be taken "subject to" the mortgage.', 'Frank. If a transfer is silent, the transferee is presumed to be "as- suming" the mortgage. 430 PROPERTY Q', 'Hector and Ignatz.', 'Neither Hector nor Ignatz.', 'C', '', '', 0, ''),
('87', 'mbe', 'mbe_0087', 'prompt_0370', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '47', '', 'What legal effect did Y''s letter have?', 'The letter dated September 2, bound both parties to a bilateral contract because Y could accept by an act or a promise.', 'The letter dated September 2, bound both parties to a unilateral contract as soon as Y mailed the letter.', 'The letter had no legal effect, al- lowing X to revoke his offer.', 'The September 2nd letter would only be an acceptance had X re- ceived Y''s letter.', 'C', '', '', 0, ''),
('870', 'mbe', 'mbe_0870', 'prompt_1184', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '106', '', 'Jerrold sold Goldacre to Kyle, who gave him a 30 year mortgage as se- curity for the purchase price. Fifteen years later, Lyle sold Goldacre to Lilly, who assumed the mortgage. As a result of the transfer, Jerrold agreed to release Kyle from the debt since the property was worth more than the outstanding mortgage. However, property values fell and the mortgage exceeded the value of the land. Lilly defaulted and Goldacre was sold at a judicial sale for less than the remaining debt. From whom can Jerrold collect the deficiency on the debt?', 'Yes. Della took the property sub- ject to the mortgage and cannot prevent the sale, even though she is not liable on the debt.', 'No. Della took the property subject to the mortgage and she is not liable on the debt. The property cannot be foreclosed upon without her consent.', 'Yes. Marcy and Bob did not pay Adam in 1970 when they received $200,000 from Della. Della should have insisted that they do so and, therefore, is not a BFP.', 'No. Della paid $200,000 to the original mortgagor, more money than the outstanding debt, there- fore, she has been equitably discharged from the mortgage.', 'B', '', '', 0, ''),
('871', 'mbe', 'mbe_0871', 'prompt_1185', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '109', '', 'In 1970, Rhetta mortgaged Redacre to Tom for $100,000. In 1980, Rhetta borrowed $45,000 from Sally and gave another mortgage on Redacre. Sally was aware of Tom''s mortgage. In 1985, Rhetta defaulted on Tom''s loan on which there was an outstand- ing balance of $80,000, and she also defaulted on her loan from Sally ow- ing $40,000. After giving notice to all relevant parties, Tom foreclosed and had the property sold at a judicial sale for $90,000 after court costs, etc. The proper distribution of the foreclosure proceeds is: Q LLI 0- 0', '$60,000 to Tom (2/3 of $90,000), $30,000 to Sally (1/3 of $90,000) — since Tom is owed twice as much as Sally by Rhetta.', '$60,000 to Tom (75% of $80,000), $30,000 to Sally (75% of 40,000) — since $90,000 is 75% of $120,000 the total amount owed.', '$50,000 to Tom, $40,000 to Sally since she is the junior mortgag- ee.', '$80,000 to Tom, $10,000 to Sally since she is the junior mortgag- ee. 432 PROPERTY', 'D', '', '', 0, ''),
('872', 'mbe', 'mbe_0872', 'prompt_1186', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '111', '', 'In 1970, Xenia mortgaged Purpleacre to Zack for $100,000. In 1980, Xenia borrowed $45,000 from Yvetta and gave another mortgage on Purpleacre. Yvetta was aware of Zack''s mortgage. In 1985, Xenia defaulted on Zack''s loan, on which there was an outstand- ing balance of $90,000, but she was not in default on the second mortgage to Yvetta. After giving notice to all relevant parties, Zack foreclosed and had the property sold to Arthur at a judicial sale for $90,000 after court costs, etc. What is the state of the title to Purpleacre after the judicial sale to Arthur?', 'Title is free and clear in Arthur. Q 0 m', 'Title is in Arthur, subject to Yvetta''s mortgage.', 'Title is free and clear in Arthur, but only if he pays the balance on Yvetta''s mortgage.', 'None of the above.', 'A', '', '', 0, ''),
('873', 'mbe', 'mbe_0873', 'prompt_1187', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '112', '', 'What is the state of the title to Yellow- acre after the judicial sale to Ed?', 'Title is free and clear in Ed.', 'Title is in Ed, subject to Ben- jamin''s mortgage.', 'Title would be free and clear in Ed, but only if the proceeds had been enough to pay the balance on Benjamin''s mortgage.', 'Title is in Benjamin, but held in trust for Ed.', 'B', '', '', 0, ''),
('874', 'mbe', 'mbe_0874', 'prompt_1188', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '113', '', 'How should the proceeds of the judi- cial sale be distributed?', 'Free and clear in Howard.', 'In Howard, subject to Gus''s mortgage.', 'In Howard, who has a claim for breach of the covenant of seisin against Fiona.', 'In Howard, who has a claim of breach of the covenant against encumbrances against Fiona.', 'C', '', '', 0, ''),
('875', 'mbe', 'mbe_0875', 'prompt_1189', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '115', '', 'In 1980, Julie mortgaged Whiteacre to Mel for $100,000. Mel did not record his mortgage, since the state''s record- ing act did not encompass property liens. In 1985, Julie sold Whiteacre by warranty deed to Kurt for $150,000. Kurt had no actual knowledge of Mel''s mortgage. What is the state of the title in 1986?', 'Free and clear in Kurt. 434 PROPERTY Q', 'In Kurt, subject to Mel''s mort- gage.', 'In Kurt, who has a claim for breach of the covenant of seisin against Julie.', 'In Kurt, who has a claim of breach of the covenant of war- ranty against Julie.', 'B', '', '', 0, ''),
('876', 'mbe', 'mbe_0876', 'prompt_1190', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '116', '', 'In 1980, Oprah mortgaged Pinkacre to Lou for $100,000. Lou did not record his mortgage since the state''s record- ing act did not encompass property liens. In 1985, Oprah sold Pinkacre by warranty deed to Ned for $150,000. Ned had no actual knowledge of Lou''s mortgage. If Ned''s property is now burdened with Lou''s mortgage, al- though not yet in default, Ned can sue Oprah:', 'He may sue Pete, but not Ruby, since the mortgage was not re- corded.', 'For breach of the covenant against encumbrances.', 'For breach of the covenant of seisin against Oprah.', 'For breach of the covenant of warranty against Oprah. PROPERTY 435', 'B', '', '', 0, ''),
('877', 'mbe', 'mbe_0877', 'prompt_1191', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '119', '', 'In 1970, Al sold Peachacre to Betty for $80,000. Betty recorded her warranty deed. In 1970, however, Peachacre was actually owned by Oscar. In 1980, Os- car sold Peachacre to Al for $90,000. That deed was recorded. In 1990, Al gave a mortgage on Peachacre to Chuck for $70,000. That mortgage was recorded. What is the state of the title after 1990?', 'Title is in Betty, free and clear.', '$70,000 to Velma, $10,000 to Umberto, since Velma is the junior interest.', '$80,000 to Umberto, since his is the first document to be re- corded.', '$70,000 to Velma, $10,000 to Umberto, since Umberto''s mort- gage is not within her chain of title. 436 PROPERTY Q', 'B', '', '', 0, ''),
('878', 'mbe', 'mbe_0878', 'prompt_1192', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '121', '', 'Gwen and Hilda owned Oliveacre as joint tenants in 1980. In 1985, Gwen 0 -0 gave a mortgage on Oliveacre to m lJI1VeilLIC 10 is.erty. VV Hal IS tile stale 1/1 the title after Gwen''s death?', 'In Hilda, free and clear.', 'In Hilda, subject to Jeremy''s mortgage.', 'In Hilda and Kelly, as tenants in common.', 'In Hilda and Kelly, as tenants in common, subject to Jeremy''s mortgage on Kelly''s share.', 'B', '', '', 0, ''),
('879', 'mbe', 'mbe_0879', 'prompt_1193', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '120', '', 'In 1980, Dwane gave a mortgage on Aquaacres to Edna for $75,000. That document was not recorded, although recoramg or liens. in i u, IJWUlle gave another mortgage on Aquaacres to Felicia for $75,000. Felicia did not have actual knowledge of the prior mortgage. Felicia recorded her mort- gage. In 1995, Dwane defaulted on both mortgages, owing $65,000 on each. Both Edna and Felicia discovered and gave notice to the other, and both foreclosed on the property. Aquaacres was sold for $65,000 after expenses. Under which types of recording acts will Felicia get the $65,000 from the foreclosure? I. Race. II. Race-Notice. III. Notice', 'I and II.', 'H and III.', 'In Mike for 2/3, 1/3 subject to Perry''s mortgage, and Orene for 1/3 as tenants in common. PROPERTY 437', 'In Mike for 1/3 subject to Perry''s mortgage, in Orene for 1/3, and in Quigley for 1/3 — all tenants in common.', 'D', '', '', 0, ''),
('88', 'mbe', 'mbe_0088', 'prompt_0371', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '48', '', 'What is the legal effect of Z''s conver- sation with Y?', 'There is no legal effect because X''s offer was irrevocable.', 'There is no legal effect because Z was making an offer to pur- chase Y''s truck.', 'Z''s conversation with Y termi- nated X''s original offer, and op- erated as an offer for Z to pur- chase Y''s truck for $7,000.', 'The conversation operated as a termination of Y''s power of ac- ceptance of X''s offer. Questions 49 - 50 are based on the following facts: Jack, a retired Olympic swimmer, decided to follow through with his long-time dream to build a large indoor swimming pool for the purpose of training youngsters for com- petition. Dan orally contracted with Jack on March 10 to build the pool, spectator bleach- ers and a parking lot. Bill has already orally agreed to permit the building of a parking lot on his', 'B', '', '', 0, ''),
('880', 'mbe', 'mbe_0880', 'prompt_1194', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '123', '', 'Renee and Sal were husband and wife who owned Taupeacre as concurrent owners in 1985. In 1990, Renee se- cretly gave a mortgage on her share in the property to Tony in exchange for $100,000. In 1995, Renee died, leav- ing the mortgage in default. If Tony wishes to sell Taupeacre at a judicial foreclosure sale, he will most likely:', 'Be able to foreclose on Renee''s heirs who own her former ten- ancy in common interest.', 'Be able to foreclose on Sal, who owns her former joint tenancy in- terest subject to the mortgage.', 'Not be able to foreclose on Sal, because Renee''s interest passed to him by right of survivorship.', 'Not be able to foreclose on Sal, because a tenancy by the entirety cannot be severed unilaterally by one member of a married couple.', 'A', '', '', 0, ''),
('881', 'mbe', 'mbe_0881', 'prompt_1195', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '124', '', 'In 1960, Beulah gave a deed of trust to Sandacre to Carlos for $150,000. In 1965, Beulah borrowed $75,000 from Delilah and gave Delilah a deed of trust on Sandacre. Delilah was aware of Carlos''s deed of trust. In 1980 Beulah defaulted on her loan to Carlos, owing him $130,000. She also defaulted on her loan to Delilah, of which $60,000 remained. Carlos fore- closed on his deed of trust, but did not give Delilah notice of the foreclosure or the resulting sale. Delilah did not foreclose. The judicial sale at Carlos''s foreclosure netted $100,000. What are Delilah''s rights in her deed of trust after Carlos''s foreclosure?', 'They are not extinguished. Since she was not given notice, the property remains subject to her deed of trust and Beulah is still liable to her personally.', 'They are extinguished. She was the junior claimant and there is no money left from the sale.', 'They are not extinguished. Since she was not given notice, she is entitled to be fully paid before Carlos.', 'They are extinguished, but only if the buyer at the foreclosure sale was unaware that Delilah was not given notice of the sale. 438 PROPERTY Q', 'A', '', '', 0, ''),
('882', 'mbe', 'mbe_0882', 'prompt_1196', 'Flemings''s Multistate Examination Workbook - Volume 2', 'property', '125', '', 'In 1970, Loni mortgaged Wheatacre to Maria for $250,000. That mortgage was recorded. In 1975, Loni borrowed $175,000 from Nash and gave Nash a mortgage on Wheatacre. Nash re- corded his mortgage. In 1980, Loni defaulted on her loan to Maria, owing her $200,000. She did not default on her loan to Nash, of which $160,000 remained. Maria foreclosed on her mortgage, but did not give Nash notice of the foreclosure or the resulting sale. The property was sold at foreclosure to Otto for $200,000. Since the foreclo- sure sale, Loni has not paid anything on her mortgage to Nash. If Nash seeks to force a judicial foreclosure sale of Wheatacre out from under Otto, he will: END OF QUESTIONS', 'Prevail, but only if Otto had actual knowledge of Nash''s mortgage.', 'Not prevail, once a senior interest forecloses at a judicial sale, all unpaid junior claims are extin- guished.', 'Prevail, but only because she was not given notice or joined in Maria''s foreclosure sale.', 'Not prevail, because Otto was a BFP who purchased at a judicial sale without Nash present and without notice of Nash''s inter- est. PROPERTY 439 440 PROPERTY PROPERTY ANSWERS C is the correct answer. The deed states that it is "subject to the understanding that...", which states a contractual obli- gation and not a limitation on the estate granted. Either a fee simple determin- able, B, or by a fee subject to condition subsequent, D, limits the estate. More- over, A is incorrect because although', 'C', '', '', 0, ''),
('883', 'mbe', 'mbe_0883', 'prompt_1228', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'property', '5', '', 'What are the rights of Infant and Agronomist?', 'in Gale, with the entire interest subject to the mortgage', 'in Gale, free and clear of the mortgage', 'half in Gale and half in Erickson, with both subject to the mortgage', 'half in Gale, free of the mortgage, and half in Erickson, subject to the mortgage 4 PROPERTY pssabso MULTISTATE SPECIALIST Question 10 is based on the following fact situation. Question 9 is based on the following fact situation. Gump, Hernandez and lba owned Blackacre, a 100 acre tract of farmland located in Shenandoah, as joint tenants with right of survivorship. After an ownership dispute arose among the three parties, Gump brought an action for partition against Hernandez and lba. While the', 'D', '', '', 0, ''),
('884', 'mbe', 'mbe_0884', 'prompt_1365', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'property', '2', '', 'created by operation of law a. fee tail after possibility of issue extinct b. dower c. curtesy d. estate during coverture II. FUTURE INTERESTS', 'Reversions', 'Possibilities of reverter', 'Rights of re-entry for condition broken (more recently called powers of termination)', 'Remainders', 'B', '', '', 0, ''),
('885', 'mbe', 'mbe_0885', 'prompt_1366', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'property', '2', '', 'executory devises created by will a. like springing uses b. like shifting uses III. CONCURRENT ESTATES (meaning ownership or possession by two or more persons at the same time)', 'Adverse Possession', 'Lateral/Subjacent Support VII. CONVEYANCING VIII. MORTGAGES ponbso MULTISTATE SPECIALIST 1 PROPERTY', 'A fee simple subject to condition subsequent is an estate in fee simple that may be terminated by the conveyor, or those claiming under him, upon the happening of a named event. However, an estate in fee simple subject to condition subsequent does not end, ipso facto, upon the happening of the named event. The estate continues despite the breach of the specified condition until it is divested by the grantor''s power of termination (or right of reentry). Smith and Boyer, Real Property, p. 9. The', 'Equitable servitudes E. Licenses VI. RTS. INCIDENT TO POSSESSION', 'B', '', '', 0, ''),
('886', 'mbe', 'mbe_0886', 'prompt_1367', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'property', '3', '', '(D) First, it is necessary to determine what interest was conveyed to Abel. According to the given facts, Owen conveyed Greenacre to "Abel upon condition precedent that he earn a college degree by age 30." If this condition occurs, title to the property would pass from Owen to Abel. As a result, Abel has a shifting executory interest which would "cut short" the preceding fee estate owned by Owen. In distinguishing between a contingent remainder and an executory interest, always remember that a contingent remainder must follow the natural termination of the preceding estate while an executory interest termi- nates the prior estate before its natural termination. Since an executory interest is contin- gent, Abel does not have the power to evict Baker who is viewed as Owen''s tenant. Once Abel''s interest "vests" upon his earning a college degree (before the age of 30), then he would have the right to immediate possession of Greenacre and have the right to terminate Baker''s tenancy. posshop MULTISTATE SPECIALIST 3 PROPERTY', 'A highly tested Multistate Property area deals with partition proceedings. First, it is important to point out that the filing of a complaint for partition does not result in the sever- ance of a joint tenancy. The rationale for this rule is that the complaint may be withdrawn at any time before the equity court compels partition. Moreover, the right of survivorship will attach if a joint tenant dies prior to that time. As a consequence, choice (D) is wrong because it provides an incorrect state', 'The Rule Against Perpetuities applies to the following six types of future interests: (1) options to purchase connected with a fee; (2) executory interests; (3) contingent remainders; (4) powers of appointment; (5) class gifts and; (6) rights of first refusal. In order to be valid, these interests must vest, if at all, within twenty-one years after some life in being. In this case, since the option extends for twenty-five years, it is possible that no interest will vest in Garp within the perpe', 'and (D) are wrong because (after Gump''s death) Hernandez and Iba continue to hold title to Blackacre as joint tenants. In this regard, students should be aware that whenever there are three (or more) joint tenants and one dies, then the survivors still own title to the property as joint tenants. On the other hand, in the event that two persons own title as joint tenants, and one of them dies, then the joint tenancy is severed and the survivor owns an undivided one-half interest in the property.', 'According to the common law rule, a mortgage results in a transfer of ownership to the mortgagee (in a title theory jurisdiction). Applying this rule, a mortgage of joint tenancy property, given by one of the joint tenants, results in a termination of the joint tenancy because it terminates the unity of title as well as the unity of interest. See Burby, Law of Property, pg. 221. Furthermore, because a tenancy in common has no unity of interest, Gale''s undivided one-half interest in Roundacre was', 'A', '', '', 0, ''),
('887', 'mbe', 'mbe_0887', 'prompt_1371', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'contracts', '1', '', 'If Barrow is later brought to trial for this charge, her best defense is that', 'Barrow didn''t know what was in the package', 'Stern didn''t tell her she was carrying illegal narcotics', 'the package didn''t belong to her', 'the cocaine was illegally seized Answer: (A) Drip purchased a used 1978 Oldsmobile convertible from Geek for $750. Their sales agreement provided that Geek was selling the car in an "as is" condition. Two days later Drip was cleaning the auto when he noticed a sealed envelope in the glove compartment. He opened the envelope and discovered it contained a small amount of hashish, a narcotic that is smoked, chewed or drunk for its intoxicating effect. Drip immediately telephoned Geek and told her w', 'A', '', '', 0, ''),
('888', 'mbe', 'mbe_0888', 'prompt_1372', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'contracts', '2', '', 'At Drip''s trial, Geek testified that the hashish was really hers and not Drip''s. She further noted that she forgot to remove the hashish from the glove compartment when she sold the car to Drip. If the jury believes Geek, Drip should be found', 'not guilty, because he did not willfully acquire the hashish and hence committed no crime', 'not guilty, because he was not the true owner of the hashish', 'Larceny at common law may be defined as the (1) trespassory (2) taking and (3) car- rying away of the (4) personal property (5) of another (6) with intent to steal it. Students must be advised that the crime of larceny requires an intent to steal, that is, an intent to deprive the owner of the possession of his (or her) property permanently or for an unreasonable length of time. Here, Pickney did not possess an intent to steal (i.e., no animus furandi). As a result, answer choice (C) is correct', 'guilty, because he acquired the hashish when he intentionally purchased the car from Geek in an "as is" condition Answer: (C) CRIMINAL LAW 2 pmabso MULTISTATE SPECIALIST', 'B', '', '', 0, ''),
('889', 'mbe', 'mbe_0889', 'prompt_1377', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'criminal', '2', '', 'If Jill is prosecuted for molesting her sepson, she should be found guilty of', 'According to Fed. Rule of Evidence 406, "Evidence of the habit of a person or of the routine practice of an organization, whether corroborated or not and regardless of the presence of eyewitnesses, is relevant to prove that the conduct of the person or organization on a particular occasion was in conformity with the habit or routine practice." Exam Tip: On the MBE the "key" words denoting habit are "always," "invariably," "customarily" and "habitu- ally." Conversely, if a person "generally" beha', 'Under Federal Rules of Evidence (F.R.E.) 401, relevant evidence is that which tends to make the existence of a fact of consequence more (or less) probable than it would other- wise be. Relevant evidence is generally admissible (F.R.E. 402), but it is inadmissible where its probative value is outweighed by the danger of unfair prejudice, confusion of the issues, misleading the jury, or by considerations of undue delay, waste of time, or needless presenta- tion of cumulative evidence (F.R.E. 403).', 'One of the most important Evidence distinctions tested on the bar exam is statements made in compromise or settlement discussions (F.R.E. 408) and admissions made in con- nection with an offer to pay medical or hospital expenses (F.R.E. 409). Statements made in compromise negotiations are not admissible. On the other hand, under F.R.E. 409 we sever and admit the admission while the offer to pay medical expenses is not admissible. Based on the given answer choices, it is necessary to assume that', 'Under F.R.E. 104(a), preliminary questions concerning the qualification of a per- son to be a witness, the existence of a privilege, or the admissibility of evidence shall be determined by the court. Preliminary questions of fact governing the application of an exclusionary rule normally are determined exclusively by the judge. The judge''s decision is final and is not subject to a contrary determination by the jury. Additionally, the judge resolves factual questions that determine the applicabil', 'B', '', '', 0, ''),
('89', 'mbe', 'mbe_0089', 'prompt_0372', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '49', '', 'Assume that Jack tendered the $13,000 on March 20, and that Dan refused to accept it, or perform. If Jack sues Dan for breach ofcontract, which defense(s) can Dan successfully use?', 'The Jack-Bill agreement was not in writing.', 'The Jack-Dan agreement was not in writing.', 'Both A and B.', 'Neither A nor B. CONTRACTS III cc 0', 'D', '', '', 0, ''),
('890', 'mbe', 'mbe_0890', 'prompt_1378', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'contracts', '1', '', 'If Amy''s parents, on her behalf, sue Mario in tort, which of the following is the most accurate state- ment regarding Mario''s post-accident statements?', 'is incorrect because Brando made the statement in a public hallway area. If another individual (other than the judge) had overheard the statement, he or she would be permit- ted to testify.', 'With respect to rulings on evidence, F.R.E. 103 provides that a timely objection or motion to strike should state the specific ground(s) for the objection. Usually, objections will either go to the "manner and form" of a question or answer or to the "substance", such as relevancy and hearsay. Here, Choice (B) is better than (A) because Kennett''s answer is non-responsive in form to the question being asked of the witness. Wawa''s attorney is ask- ing Kennett the date the mushrooms were shipped and', 'F.R.E. 407 allows evidence of subsequent remedial measures when offered to show ownership or control. If the tree was on city property and thus the responsibility of the city, it is unlikely that Dow would have it cut down. Such evidence is therefore admissible, under answer choice (C), to show the tree was on his property.', 'is correct. Caveat: Students must carefully read the call of the question. In this case, Loscutoff, the prosecution witness, is being called to testify before the facts tell you that Wapner, the defendant, has presented any evidence. Therefore, the testimony of Loscutoff, which might have been proper rebuttal testimony at some later point in the trial, will be inadmissible at this point.', 'A', '', '', 0, ''),
('891', 'mbe', 'mbe_0891', 'prompt_1382', 'PMBR - Multistate Early Bird MBE - Questions & Answers (2007)', 'constitutional', '1', '', 'Can Lansing impose this tax on Quicksilver''s delivery operations within the state?', 'Yes, because Congress has the power to regu- late property for the general welfare.', 'Yes, because Congress could determine that in inseverable aggregates bicycle thefts affect interstate commerce.', 'No, because most stolen bicycles remain within the state in which they were stolen.', 'No, because the registration of vehicles is a matter reserved to the states by the Tenth Amendment. Answer Key: 1. A', 'A', '', '', 0, ''),
('9', 'mbe', 'mbe_0009', 'prompt_0036', 'Barbri - Drills and Released Questions - MDR (MBE - 2007)', 'property', '68', '', 'REAL PROPERTY Question 17 Augustus received an “inside tip” from his friend Drusus, a real estate developer. Acting on the tip, Augustus purchased several acres of scrub-covered land of little apparent value. Shortly thereafter, Whizny World, an interna- tional conglomerate, announced plans to de- velop a theme park to be called “Romeland” on a tract immediately adjacent to Augustus’s scrubland. The Whizny World plan caused real estate values in the surrounding area to sky- rocket. Augustus could have sold his land for a price many times greater than the purchase price, but Augustus decided that he would use the land to build a variety of tourist-oriented facilities. In order to finance his project, Augustus went to Brutus Bank (“Brubank”) and took out a $20,000 mortgage on his land. Brubank promptly recorded the mortgage. A few days later, Augustus went to Cassius Bank (“Casbank’’) and took out a $15,000 mortgage on the land. Casbank had known of the Brubank mortgage, and Casbank promptly recorded its own mortgage. A few weeks after that, Augustus reviewed his plans and decided that he needed more money to make his proposed tourist facilities more “upscale.” Augustus went back to Brubank and, after full disclosure of the Casbank mortgage, asked the loan officer if he could receive another advance of $15,000 from the original Brubank mortgage. The loan officer readily agreed, processed the loan, and increased the amount borrowed against the mortgage from $20,000 to $35,000. Brubank promptly recorded the change. Augustus quickly spent most of his available funds on retainers for architects, builders, and attorneys. He was shocked to read in the paper that the County Council summarily rejected the Whizny World proposal, acceding to the argu- ments of community activists and environmen- talists that the economic benefits from the theme park would be outweighed by the deleterious effects on the natural beauty and tranquility of the area. Augustus made no more mortgage p', '$18,000 to Brubank and nothing to Casbank.', '$9,000 to Brubank and $9,000 to Casbank.', '$3,000 to Brubank and $15,000 to Casbank.', 'Nothing to Brubank, $15,000 to Casbank, and $3,000 to Augustus. STOP borort BAR REVIEW ®®OO ®®OO ®®OO OROKOTO) ®®OOO oa Pp oD = ®®OO (OROKORO) ®®©OO (OROROLO) ®®©OO SYP AND', 'A', '', '', 0, ''),
('90', 'mbe', 'mbe_0090', 'prompt_0373', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '50', '', 'Assume that Jack paid the $13,000 on March 20, and that Dan completed the pool and bleachers, according to speci- fications. However, Jack then refused to pay the second installment, and re- pudiates the contract. Which of the fol- lowing is correct?', 'Dan has a cause of action against Jack for $5,000 in damages.', 'Dan can refuse to finish the park- ing lot, and not be liable for breach of contract.', 'Both A and B.', 'Neither A nor B.', 'A', '', '', 0, ''),
('91', 'mbe', 'mbe_0091', 'prompt_0374', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '52', '', 'Seller, contracted in writing to deliver to Buyer, 10,000 cartons of milk on May 1 at $ 1.00 a carton. Because the farmers who supplied Seller with his milk did not deliver enough milk, Seller only had 9,000 cartons of milk to ful- fill his contract with Buyer. If Seller tenders only 9,000 cartons of milk to Buyer on May 1, and Buyer refuses to accept, or pay for any, which is the best statement regarding their contractual relationship?', 'The doctrine of impossibility of performance excuses Seller from performing the contact.', 'Seller can sue Buyer since he substantially performed the con- tract.', 'Buyer is obligated to give Seller time to cure. 72 CONTRACTS', 'Buyer has a cause of action against Seller for Seller''s failure to deliver 10,000 cartons ofmilk.', 'B', '', '', 0, ''),
('92', 'mbe', 'mbe_0092', 'prompt_0375', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '53', '', 'Miller started a car wash in Columbus, Ohio. He leased his equipment from Americo in 1987, under a five-year lease which was renewable for 3 one-year periods. At the end of eight years, Americo would "abandon" the equipment to Miller (he would have paid for it in full). In May 1991, Miller defaulted. Americo repossessed and re- sold the equipment. Americo claims it is owed $2,000 by Miller, under a lease provision which provides that Americo could collect 10% of the equipment''s total cost in the event of any default. Miller claims the liquidated damages clause is invalid. Is the liquidated dam- ages clause valid?', 'Yes, because there was a meet- ing of the minds.', 'Yes, because it is to determine whether or not Miller would de- fault at the inception ofthe lease.', 'No, because a 10% liquidated damages clause in any contract is unconscionable as a matter of law.', 'No, because the damages to Americo would not be difficult to ascertain. Questions 54 - 55 are based on the following facts: In a written contract, Manufacturer agreed to deliver to Baker, 200 described chairs at $100 each EO.B., at Manufacturer''s place ofbusiness. The contract provided that "nei- ther party will assign the contract without written consent of the other." Manufacturer placed the chairs on the carrier on August', 'D', '', '', 0, ''),
('93', 'mbe', 'mbe_0093', 'prompt_0376', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '54', '', 'In an action by Wheeler against Baker for breach ofcontract, Wheeler will re- cover:', '$20,000, the contract price.', 'The difference between the con- tract price and the market value of the chairs.', 'Nothing, because the chairs had not been delivered.', 'Nothing, because the Manufac- turer and Baker contract forbid an assignment.', 'A', '', '', 0, ''),
('94', 'mbe', 'mbe_0094', 'prompt_0377', 'Flemings''s Multistate Examination Workbook - Volume 1', 'property', '55', '', 'In an action by Baker against Manufac- turer for breach ofcontract, Barker will probably:', 'Succeed, since the risk of loss was on Manufacturer. CONTRACTS &I', 'Succeed, since the contract was not assigned.', 'Not succeed, since the risk of loss was on Baker.', 'Not succeed, since the chairs were destroyed making it impos- sible for Manufacturer to per- form.', 'B', '', '', 0, ''),
('95', 'mbe', 'mbe_0095', 'prompt_0378', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '56', '', 'Billy Joe, a disabled veteran, contracted to purchase a certain piece ofland from Jermey. The property consisted of a tract ofland containing the famous tour- ist attraction, "Blue Lagoon". Billy was excited because he could now be a ho- meowner and receive income in order to pay the land payments and his living expenses. After BillyJoe purchased the property, he discovered that the home site was on Federal Reserve Land, and that the income from the lagoon was $36,000 rather than $39,000 as repre- sented. Billy Joe sued Jermey. Billy Joe can: Recover money damages only. II. Rescind the contract.', 'I only.', 'II only.', 'lor II.', 'Neither I nor II. III CONTRACTS', 'A', '', '', 0, ''),
('96', 'mbe', 'mbe_0096', 'prompt_0379', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '57', '', 'The Bank of Commerce Inc. ("BCI") loaned the Bombay Company $1 mil- lion for the manufacture of a new type of computer chip. As a condition of the loan, Wendy Wonder, a majority share- holder in Bombay, agreed in writing to personally guarantee the loan. There- after, Bombay defaulted on the loan and entered into a repayment agreement with BCL This agreement provided that BCI would "use maximum efforts in selling Bombay''s assets at the highest possible price." BCI proceeded to sell Bombay''s assets, discharging the in- debtedness of the Bombay Company. Later, it was ascertained that BCI did not realize the "highest possible price" in administering the sale of Bombay''s assets. Consequently, Wendy was forced into bankruptcy and lost her en- tire investment in the Bombay Com- pany. Wendy brings an appropriate action against BCI to recover her investment in Bombay''s stock. She will most likely:', 'Not prevail, because Wendy was an incidental beneficiary of the BCI sale of Bombay''s assets.', 'Not prevail, because BCl''s sale of Bombay''s assets discharged whatever contractual relation- ship existed between Wendy and the bank.', 'Prevail, because BCI did not re- alize the highest possible price from the sale ofBombay''s assets.', 'Prevail, because BCI breached its fiduciary duty to Wendy un- der the terms ofthe BCI-Bombay contract. Questions 58 - 59 are based on the following facts: On January 5, Prevention Company, a manu- facturer of steel security blinds for homes, received the following order from Lion Homes: "Please ship 500 4'' x 6'' security shut- ters. Delivery by March 10." On February 10, Prevention shipped 500 4'' x 8'' security shutters, which were received by Lion on February 12. The following day Lion''s foreman,', 'D', '', '', 0, ''),
('97', 'mbe', 'mbe_0097', 'prompt_0380', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '58', '', 'Did Lion properly refuse the first ship- ment delivered on February l2?', 'No, because Lion waived its right to reject the nonconform- ing goods by not returning them. CONTRACTS iii', 'No, because Prevention could accept Lion''s offer by prompt shipment ofeither conforming or nonconforming goods.', 'Yes, because the security shut- ters were nonconforming.', 'Yes, because Prevention did not notify Lion that the 4'' x 8'' secu- rity shutters were for accommo- dation only.', 'A', '', '', 0, ''),
('98', 'mbe', 'mbe_0098', 'prompt_0381', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '59', '', 'Did Lion properly reject the security shutters delivered on March 7?', 'No, because, under the VCC, a contract for the sale ofgoods can be modified without consider- ation.', 'No, because Prevention cured the February 10 defective ship- ment by tender of conforming goods on March 7.', 'Yes, because Prevention''s ship- ping of the 4'' x 8'' security shut- ters on February constituted an- ticipatory breach.', 'Yes, because Prevention''s ship- ping of the 4'' x 8'' security shut- ters on February 10 constituted a present breach. m CONTRACTS Questions 60 - 61 are based on the following facts: Tom wanted to have a security system in- stalled in his home. He contacted several companies and had them submit bids for the installation ofthe system. SecureCo, in tum, requested bids from several wholesalers for prices of burglar alarm components which it planned to use if awarded the job. BurgCo submitted a bid to', 'A', '', '', 0, ''),
('99', 'mbe', 'mbe_0099', 'prompt_0382', 'Flemings''s Multistate Examination Workbook - Volume 1', 'contracts', '60', '', 'In an action by SecureCo against Tom, SecureCo will be able to recover:', '$5,000, because that was the con- tract price.', '$6,000, because of an unantici- pated change of circumstances.', 'Only in quantum merit, because SecureCo did not intend to oper- ate at a loss.', 'Only in quantum meruit, because by demanding $6,000 SecureCo repudiated its contract with Tom.', 'D', '', '', 0, ''),
('civ0001', 'workshop_civpro', 'civ0001', 'civ0001', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '1', 'A corporation filed a breach of contract action against another corporation in the United States District Court for the District of State A on the basis of diversity of citizenship jurisdiction. The action seeks $80,000 in damages. The plaintiff corporation was incorporated in State B and has its principal place of business in State C. The defendant corporation was incorporated in State C and has its principal place of business in State A. The defendant corporation filed a motion to dismiss the action for lack of subject matter jurisdiction. Will the defendant corporation’s motion be granted?', 'Yes, because both corporations are citizens of State C.', 'Yes, because the defendant corporation is a citizen of the state in which the action was filed.', 'No, because the plaintiff corporation is a citizen of State C and the defendant corporation is a citizen of State A.', 'No, because, while both corporations are citizens of State C, the plaintiff corporation is also a citizen of State B and the defendant corporation is also a citizen of State A.', 'D', '', 'civ0001', 0, NULL),
('civ0002', 'workshop_civpro', 'civ0002', 'civ0002', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '2', 'A building materials supplier, who is a citizen of State A, and a contractor, who is a citizen of State B, had a contract dispute. The contractor drove to the supplier’s home in State A to discuss possible settlement of the dispute. The discussions were not successful. As the contractor backed out of the supplier’s driveway, the contractor accidently hit the supplier’s car, damaging it significantly. The supplier sued the contractor in federal court, asserting both a breach of contract claim and a negligence claim for the damage done to the supplier’s car. The supplier’s complaint seeks $71,000 in damages for breach of contract and $5,000 in damages to pay the cost of repairs to the car. Does the federal court have subject matter jurisdiction over the supplier’s action?', 'Yes, because the amounts of the supplier’s two claims may be aggregated and thus meet the amount in controversy requirement.', 'Yes, because the supplier’s two claims are related and therefore may be aggregated to satisfy the amount in controversy requirement.', 'No, because the supplier’s two claims do not arise from the same transaction or occurrence and therefore may not be aggregated to satisfy the amount in controversy requirement.', 'No as to the negligence claim but yes as to the breach of contract claim.', 'A', '', 'civ0002', 0, NULL),
('civ0003', 'workshop_civpro', 'civ0003', 'civ0003', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '', '3A driver was killed in a two-car accident in State A. The deceased driver was a citizen of State B, and the driver of the other car is a citizen of State A. The executor of the deceased driver’s estate filed a negligence action in federal district court on behalf of the deceased driver against the State A driver, seeking $250,000. The executor is a citizen of State A. Does the federal court have diversity of citizenship jurisdiction over this action?', 'No, because the executor and the defendant are both citizens of State A.', 'No, because federal courts will not exercise diversity of citizenship jurisdiction over probate matters.', 'Yes, because the executor of the plaintiff’s estate is a citizen of State A and the deceased plaintiff is a citizen of State B.', 'Yes, because the deceased plaintiff was a citizen of State B and the defendant is a citizen of State A.', 'A', '', 'civ0003', 0, NULL),
('civ0004', 'workshop_civpro', 'civ0004', 'civ0004', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '4', 'A seller entered a contract with a buyer under which the buyer agreed to purchase certain corporate securities for $500,000. The buyer refused to go through with the purchase, contending that the entire transaction was void because of federal securities statutes. The seller thus sold the securities to another party but was able to sell them for only $420,000. The seller filed an action against the buyer in federal district court, alleging that the transaction did not violate federal securities statutes and seeking $80,000 for the buyer’s breach of contract. The seller and the buyer are both citizens of the same state. Does the federal court have subject matter jurisdiction over the action?', 'Yes, because the action raises the federal issue of whether the transaction violated federal securities statutes.', 'Yes, because the amount in controversy exceeds the required minimum for purposes of federal question jurisdiction.', 'No, because the buyer and seller are citizens of the same state and the action does not arise under federal law.', 'No, because the amount in controversy for purposes of federal question jurisdiction is not sufficient.', 'C', '', 'civ0004', 0, NULL),
('civ0005', 'workshop_civpro', 'civ0005', 'civ0005', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '5', 'A citizen of State A filed a breach of contract action against a citizen of State B in a State A state trial court. The State B defendant timely and properly removed the action to the United States District Court for the District of State A. The defendant then filed a motion to dismiss the action based on insufficient service of process. Following a hearing, the court found that service was proper and denied the motion. The defendant then filed her answer, responding to the merits of the complaint and asserting that the case should be dismissed on the grounds that another action was pending between the same parties for the same cause in a State B state court. The State A Rules of Civil Procedure provide that a party waives the right to seek dismissal on that ground if the party files a pre-answer motion to dismiss and does not assert that ground in the motion. Should the federal court hold that the defendant has waived the right to seek dismissal based on the pendency of the same cause in another court?', 'Yes, because this action was commenced in a State A state court, so the federal court must apply State A law.', 'Yes, because this action is in a federal court in State A on the basis of the court’s diversity of citizenship jurisdiction, so the federal court must apply State A law.', 'No, because this issue is unlikely to affect the outcome of the action or to create forum-shopping, so the federal court should apply federal law, under which the defendant has not waived this defense.', 'No, because this issue is governed by the Federal Rules of Civil Procedure, under which the defendant has not waived this defense.', 'D', '', 'civ0005', 0, NULL),
('civ0006', 'workshop_civpro', 'civ0006', 'civ0006', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '6', 'A researcher and an analyst had employment contracts with a corporation. The corporation fired them because it believed they had conspired to give its trade secrets to a competitor. Knowing that the conspiracy allegations were not true, the researcher and the analyst sued the corporation in federal district court for breach of their employment contracts. The researcher seeks $100,000 in damages and the analyst seeks $50,000. They are both citizens of State A. The corporation is incorporated in State B, and its principal place of business is in State B. Does the federal district court have subject matter jurisdiction over both of the claims?', 'Yes, the court has diversity of citizenship jurisdiction over both claims because the amounts of their related claims may be aggregated to satisfy the amount in controversy requirement.', 'Yes, the court has diversity of citizenship jurisdiction over the researcher’s $100,000 claim and supplemental jurisdiction over the analyst’s $50,000 claim.', 'No, the court does not have subject matter jurisdiction over the analyst’s $50,000 claim because the claims of both plaintiffs may not be aggregated to satisfy the amount in controversy requirement.', 'No, the court does not have subject matter jurisdiction over either claim because the breach of contract claim is based on state law.', 'B', '', 'civ0006', 0, NULL),
('civ0007', 'workshop_civpro', 'civ0007', 'civ0007', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '7', 'A pedestrian was injured in a car accident involving two cars. The pedestrian filed a negligence action against both drivers in federal district court, seeking to hold them jointly and severally liable for $500,000. The pedestrian is a citizen of State A, and both drivers are citizens of State B. The first driver then asserted a cross-claim against the second driver, claiming that the second driver’s negligence was the sole cause of the accident and seeking to recover from the second driver $15,000 for the damage done to the first driver’s car. Does the federal court have subject matter jurisdiction over the cross-claim?', 'No, because the cross-claim is between two citizens of the same state.', 'No, because the amount of the cross-claim is too small.', 'No, because there is no supplemental jurisdiction over the cross-claim unless it is related to a federal question claim asserted in the same action, and there is no federal question claim.', 'Yes, the court has supplemental jurisdiction over the cross-claim.', 'D', '', 'civ0007', 0, NULL),
('civ0008', 'workshop_civpro', 'civ0008', 'civ0008', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '8', 'An investor filed a civil action against her broker in a State A state court seeking $30,000 for violation of federal securities statutes. The investor is a citizen of State B and the broker is a citizen of State A. May the broker remove the action to federal district court?', 'No, because the amount in controversy is too small for federal subject matter jurisdiction.', 'No, because the defendant is a citizen of the state from whose court the action is removed.', 'Yes, the broker may remove the action to federal district court on the basis of federal question jurisdiction.', 'Yes, the broker may remove the action to federal district court on the basis of federal diversity of citizenship jurisdiction.', 'C', '', 'civ0008', 0, NULL),
('civ0009', 'workshop_civpro', 'civ0009', 'civ0009', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '9', 'A car buyer, a resident of State A, wished to purchase a new car. After shopping both online and in person for the best price, the buyer decided to purchase a car from a dealer in State B. The buyer drove to the State B dealership, signed a sales contract, paid for the car, and drove the car back home to State A. Three months later, the buyer was in an accident in State A while driving the new car. The other driver in the accident was a resident of State B who was just passing through State A. The other driver filed a negligence action against the buyer in a court in State B. Does the buyer have sufficient contacts with State B such that a State B court could exercise personal jurisdiction over the buyer for the negligence action?', 'Yes, because the buyer had purposeful contacts with State B.', 'No, because the other driver’s claim does not arise from the buyer’s contacts with State B, and the contacts are insufficient to create general personal jurisdiction.', 'No, because the buyer did not benefit in any way from the contacts with State B.', 'No, because the buyer’s contacts with State B were not purposeful.', 'B', '', 'civ0009', 0, NULL),
('civ0010', 'workshop_civpro', 'civ0010', 'civ0010', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '10', 'A hunter residing in State A visited a website created and operated by a hunting equipment company. The company is a State B corporation, and its headquarters and all its facilities are in State B. It sells its products in several stores in State B and through its website. Its marketing efforts and most of its sales are in State A and State B. Using the company’s website, the hunter ordered a hunting stand. The hunter paid for the stand and shipment to State A by providing his credit card information on the company’s website. After the stand arrived at the hunter’s home in State A, the hunter used the stand while on a hunting trip in State C—a very popular hunting destination. The stand collapsed, causing severe injuries to the hunter. The hunter filed a products liability action against the company in a State C court. The company filed a motion to dismiss the action on the ground that the State C court lacks personal jurisdiction over it. Although the company’s website is accessible in State C, the company does not otherwise advertise there, and it does no business there. There is no evidence that the company has sold any products in State C. Does the company have sufficient contacts with State C such that a State C court may exercise personal jurisdiction over it?', 'Yes, because the company’s website is continuously accessible in State C so that people there may purchase products from the company at any time.', 'Yes, because the company could foresee that its customers would carry the company’s hunting products on hunting trips to other states—particularly states where hunting is popular.', 'No, because personal jurisdiction cannot be based on Internet contacts.', 'No, because the company does not have sufficient purposeful contacts with State C.', 'D', '', 'civ0010', 0, NULL),
('civ0011', 'workshop_civpro', 'civ0011', 'civ0011', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '11', 'An automobile crash victim intends to file a negligence action based on diversity of citizenship jurisdiction against a driver in federal court for injuries sustained in an automobile accident that occurred in State A. The victim resides in State B, and the driver resides in State C. State A, State B, and State C all have only a single federal judicial district. In which federal district court(s) is venue proper?', 'The District of State A only.', 'The District of State C only.', 'The District of State A and the District of State C.', 'The District of State A, the District of State B, and the District of State C.', 'C', '', 'civ0011', 0, NULL),
('civ0012', 'workshop_civpro', 'civ0012', 'civ0012', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '12', 'A zoologist was moving to State A from State B, where she had lived her entire life. She was driving a truck and trailer that contained all of her possessions across the country when she was involved in a severe accident in State C. After being released from the hospital, but before suit was filed, the zoologist proceeded to State A, where she rented an apartment and found a job. The driver of an automobile involved in the severe accident intends to file a negligence action against the zoologist in federal district court. The driver is a citizen and resident of State D. In which federal district(s) is venue proper?', 'The District of State C only.', 'The District of State C and the District of State B.', 'The District of State C and the District of State A only.', 'The District of State C, the District of State D, and the District of State A.', 'C', '', 'civ0012', 0, NULL),
('civ0013', 'workshop_civpro', 'civ0013', 'civ0013', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '13', 'A plaintiff from State A filed a breach of contract action in a federal court in State B. The defendant in the action is a State B corporation. The corporation’s president and registered agent, the only officer having express authority to receive service of process on behalf of the corporation, was out of the country for several months. State B’s rules of civil procedure, however, authorize service on a corporation by serving any “officer, managing or general agent, or any agent authorized to receive service.” State B’s rules also authorize service of process by certified mail. The plaintiff thus sent the summons and complaint to the defendant corporation’s only vice president, who resides in State B. The vice president signed the certified mail return receipt. If the corporation files a motion to dismiss the action for improper service of process, how should the court rule?', 'Deny the motion, because service of process was proper.', 'Deny the motion, because the defendant waived service of process by allowing its only agent authorized to receive service to leave the country.', 'Grant the motion, because, despite what state rules allow, service on a corporation sued in federal court must be on the officer or agent of the corporation who is authorized by the corporation to receive service on behalf of the corporation.', 'Grant the motion, because, despite what state rules allow, service on a corporation sued in federal court may not be made by certified mail.', 'A', '', 'civ0013', 0, NULL),
('civ0014', 'workshop_civpro', 'civ0014', 'civ0014', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '14', 'After filing her complaint in federal district court, a plaintiff mailed to a defendant by ordinary first-class mail the following: duly executed copies of the complaint and summons, a request that the defendant waive service of process, two copies of a waiver-of-service form, and an addressed, prepaid return envelope. The defendant signed the waiver-of-service form and returned a copy to the plaintiff. Fifty days after the plaintiff mailed the forms to the defendant and 25 days after the defendant returned the signed form to the plaintiff, the plaintiff filed a motion for entry of default and a default judgment. The following day, the defendant filed and served his answer. Was the defendant’s answer timely?', 'No, because the defendant may no longer file an answer once the time for filing a response to a complaint has expired and the plaintiff has filed a motion for default judgment.', 'No, because the Federal Rules of Civil Procedure require a defendant to file a response to a complaint within 21 days after being served with process.', 'Yes, because the defendant filed his answer less than 28 days after he returned the waiver of service form.', 'Yes, because a defendant who waives service of process is allowed additional time in which to respond to the complaint, and the time had not yet expired.', 'D', '', 'civ0014', 0, NULL),
('civ0015', 'workshop_civpro', 'civ0015', 'civ0015', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '15', 'A customer became ill from meat he purchased at the “The Corner Grocery” store in City A. The legal name of the store is “The Corner Grocery, Inc.” The customer’s attorney instituted a diversity action in federal district court, mistakenly naming as the defendant “The Corner Grocery” in City B, whose legal name is “The Corner Grocery Company, Ltd.” The two are separate legal entities, but their stock is owned by the same persons in the same proportions. The complaint specifically described the store from which the pork was purchased, including its City A address. Approximately one month after filing the complaint, and after the statute of limitations had expired, the customer’s attorney served process on an individual who is the president and 50% shareholder of both stores. The named defendant, the City B store, then filed its answer denying liability on the grounds that the customer never visited the City B store and never bought anything there. Upon learning that he had named the wrong store as defendant, the customer’s attorney filed a motion to amend the complaint to substitute the name of the correct defendant for the incorrect defendant originally named. After the court allowed the amendment, the new defendant filed an answer asserting that the claim against it was barred by the statute of limitations. In response, the customer’s attorney asserted that the amended complaint is not barred because it asserts a claim that arises from the same transaction as the original complaint and therefore relates back to the time of the original complaint. Is the amended complaint barred even though it relates back to the time of the original complaint?', 'No, because the customer appears to have acted in good faith and exercised reasonable care in naming the proper defendant.', 'No, because the new defendant received timely notice of the action so as not to be prejudiced in defending the merits and knew or should have known that the action would have been brought against it but for a mistake concerning the proper party’s identity.', 'Yes, because the proper defendant was not served with process within the time prescribed for service of the original complaint.', 'Yes, because both the original and the amended claims are barred by the statute of limitations since service of process did not occur until after the statute of limitations expired.', 'B', '', 'civ0015', 0, NULL),
('civ0016', 'workshop_civpro', 'civ0016', 'civ0016', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '16', 'A bar prep company discovered that its copyrighted content was being used in an online simulated exam that its competitor was administering in a few days. The company filed a petition for an ex parte order to direct the competitor to immediately remove that content from its website. The company submitted an affidavit specifying why immediate and irreparable injury will result if the exam is administered, and offered to provide security for any costs or damages incurred by the competitor if it was determined that the order was wrongfully issued. Should the court issue the order?', 'Yes, because the company submitted an affidavit with specific facts showing immediate and irreparable injury.', 'Yes, because the competitor will receive notice of the order once it is issued by the court.', 'No, because a court cannot issue an injunction unless the adverse party has notice of the hearing.', 'No, because the company has not provided sufficient certification for obtaining an ex parte order.', 'A', '', 'civ0016', 0, NULL),
('civ0017', 'workshop_civpro', 'civ0017', 'civ0017', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '17', 'Two citizens of State A were injured in State B when the taxi in which they were riding was in an accident. The two State A citizens intend to file tort claims against the taxi driver, a citizen of State B, in federal district court seeking over $100,000 each. May or must they assert their claims in federal district court in a single civil action?', 'They must assert their claims in a single action because their claims arise from the same accident.', 'They may assert their claims in a single action if they wish, or they may file separate actions.', 'They may not assert their claims in a single action because they are not asserting a single undivided interest.', 'They may not assert their claims in a single action because each plaintiff is seeking damages for his own discrete bodily injuries.', 'B', '', 'civ0017', 0, NULL),
('civ0018', 'workshop_civpro', 'civ0018', 'civ0018', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '18', 'Three drivers were in a traffic accident in State A. The three drivers were citizens of State A, State B, and State C, respectively. Only the driver from State C sustained any injuries and damage. The driver from State C filed a tort action against the State A driver, seeking $100,000 in damages. The State A driver believes that he was not at fault in any way and that the driver from State B was the sole cause of the accident. Assume State A does not recognize any claim of contribution among joint tortfeasors. May the State A driver assert a third-party claim against the State B driver in the pending action, alleging that the State B driver was the party at fault and should pay for the State C driver’s injuries?', 'Yes, because third-party claims are permitted as long as they arise from the same transaction or occurrence as the original action.', 'Yes, because the State A driver’s third-party claim is derivative of the State C driver’s original claim.', 'Yes, provided the State A driver obtains leave of the court.', 'No, the State A driver may not maintain the third-party claim.', 'D', '', 'civ0018', 0, NULL),
('civ0019', 'workshop_civpro', 'civ0019', 'civ0019', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '19', 'The plaintiff in a negligence case was injured in a car accident with the defendant. The plaintiff’s attorney retained a physician to examine the plaintiff and to testify regarding the plaintiff’s injuries. After the physician examined the plaintiff, the plaintiff’s attorney discussed the physician’s findings with the physician. The plaintiff’s attorney and the physician also discussed what the physician should include in the expert witness report that will be provided to the defendant. The defendant then conducted a deposition of the physician. During the deposition, the defendant’s attorney asked the physician to describe what was said in his conversations with the plaintiff’s attorney. The plaintiff’s attorney objected to those questions. Are the defendant’s questions regarding the plaintiff’s attorney’s discussions with the physician properly subject to discovery?', 'No, because the communications between the plaintiff’s attorney and the physician are protected from discovery under the work product doctrine.', 'No, because the communications between the plaintiff’s attorney and the physician are protected by the attorney-client privilege.', 'Yes, because the attorney does not represent the physician and therefore the communications between the plaintiff’s attorney and the physician are not privileged.', 'Yes, because the communications between the plaintiff’s attorney and the physician are relevant to determine the basis for opinions and statements in the physician’s expert report.', 'A', '', 'civ0019', 0, NULL),
('civ0020', 'workshop_civpro', 'civ0020', 'civ0020', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '20', 'A former shareholder of a corporation filed an action against the corporation’s board of directors, alleging that the directors’ wrongful actions diminished the value of the corporation and its stock. The former shareholder served a request for production of documents that included a request for any documents relating to the value of the corporation. The corporation produced a number of documents, but withheld certain documents that were written by its attorneys, claiming that the documents were protected from discovery under the attorney-client privilege. Without contacting or conferring with the corporation or its lawyer, the former shareholder filed a motion to compel production of the withheld documents, claiming that they were not covered by the privilege. The court ruled that the documents were not privileged and had to be produced. What will be the likely result if the former shareholder seeks to recover costs or attorneys’ fees related to the motion or to have sanctions imposed on the corporation?', 'The shareholder may not recover costs or attorneys’ fees or have sanctions imposed.', 'The shareholder may recover the costs of asserting the motion to compel but may not recover any attorneys’ fees or have sanctions imposed.', 'The shareholder may recover the costs and attorneys’ fees incurred in asserting the motion to compel, but may not have sanctions imposed.', 'The shareholder may recover costs and attorneys’ fees incurred in asserting the motion to compel, and may have sanctions imposed.', 'B', '', 'civ0020', 0, NULL),
('civ0021', 'workshop_civpro', 'civ0021', 'civ0021', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '21', 'The plaintiff and defendant in a negligence action filed in federal district court were in a two-car accident. The defendant’s attorney properly gave notice of and commenced a deposition of an eyewitness to the accident. Attorneys for both parties were present at the deposition. During the deposition, the defendant’s attorney asked the witness a leading question, and the plaintiff’s attorney did not object. At the time of trial, the eyewitness was out of the country. Therefore, the defendant’s attorney sought to read a portion of the witness’s deposition testimony into evidence at trial, including the leading question and the witness’s response to it. The plaintiff’s attorney objected at trial to the reading of the leading question and the witness’s response. Is the leading question and response properly admissible in evidence at trial?', 'No, because none of the deposition testimony is admissible in evidence under these circumstances.', 'No, because, while the deposition testimony is generally admissible under these circumstances, the court may exclude the leading question and answer on the basis of the plaintiff’s objection at trial.', 'Yes, because the deposition testimony is generally admissible under these circumstances, and the plaintiff waived any objection to the leading question because the plaintiff did not object to the question at the deposition.', 'Yes, because once a part of the deposition testimony is admissible under these circumstances, all of the deposition is admissible regardless of the plaintiff’s objection.', 'C', '', 'civ0021', 0, NULL),
('civ0022', 'workshop_civpro', 'civ0022', 'civ0022', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '22', 'A hotelier entered into a contract with a merchant to have the merchant build and deliver custom furniture having a total cost of $1 million. The hotelier is a resident of State A and the merchant is a resident of State B. The merchant completed the furniture but the hotelier refused delivery, claiming that the furniture was not as the hotelier and merchant had agreed. The hotelier then filed an action against the merchant in federal district court, claiming breach of contract and seeking the return of a $100,000 deposit. The merchant filed an answer, denying liability and denying that it breached the contract. At the same time, the merchant filed and served a counterclaim asserting that the hotelier had breached the contract and seeking the $900,000 balance due. A week after being served with the merchant’s answer and counterclaim, the hotelier filed a voluntary dismissal of the action. Is the hotelier’s dismissal effective?', 'Yes, because the party that commenced an action may always terminate it.', 'Yes, because a plaintiff may voluntarily dismiss an action of right if the plaintiff does so within 21 days of the defendant filing an answer.', 'No, because, while the hotelier otherwise would have had the right to dismiss the action, the hotelier cannot voluntarily dismiss the action because of the merchant’s pending counterclaim.', 'No, because, after a defendant files an answer, an action may be dismissed only by a stipulation signed by all parties or by an order of the court.', 'C', '', 'civ0022', 0, NULL),
('civ0023', 'workshop_civpro', 'civ0023', 'civ0023', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '23', 'An office furniture supplier filed a breach of contract action against a law firm in federal district court to recover the balance due on an account for furniture it supplied. The law firm filed a motion to dismiss the action on the ground that service of process was improper. Following a hearing, the court held that service was proper and sufficient. Two more months passed without the law firm filing an answer. The supplier then filed a motion to have the clerk of court make an entry of default, and the clerk did so. What procedure must the supplier follow to obtain a default judgment against the law firm?', 'File a motion to have the clerk of court enter the default judgment, and the clerk may do so without the law firm receiving any further notice of the motion.', 'File a motion to have the clerk of court enter the default judgment, and the clerk may do so as long as the law firm receives additional notice of the motion for default judgment.', 'File a motion to have the judge enter the default judgment, and the judge may do so without the law firm receiving any further notice of the motion for default judgment.', 'File a motion to have the judge enter the default judgment, and the judge may do so as long as the law firm receives additional notice of the motion for default judgment.', 'C', '', 'civ0023', 0, NULL),
('civ0024', 'workshop_civpro', 'civ0024', 'civ0024', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '24', 'The owner of property bordering a river properly brought suit in federal court against a power company, alleging that the power company dumped radioactive waste water from one of its nuclear plants into the river, causing the property owner many health issues and resulting in the diminution of his property’s value. The suit sought damages and a preliminary injunction forbidding the power company from dumping any waste into the river. The power company was provided with notice of the hearing, to which it sent its lawyer. During the hearing, the power company claimed that it has complied with applicable state and federal environmental regulations, and stated that it will continue to comply with the regulations if the injunction is denied. The judge granted the preliminary injunction and set a date for a pretrial conference, as required by the Federal Rules of Civil Procedure. May the power company immediately appeal the judge’s granting of the preliminary injunction?', 'No, because the order is not final.', 'No, because the question has not been certified as one falling within the Interlocutory Appeals Act.', 'Yes, but only if the power company takes a default judgment, thereby making the judgment final.', 'Yes, because the order is immediately appealable as of right.', 'D', '', 'civ0024', 0, NULL),
('civ0025', 'workshop_civpro', 'civ0025', 'civ0025', '698549435-CIVIL-PROCEDURE-MBE-QUESTIONS.pdf', 'Civil Procedure', '', '25', 'A plaintiff filed a single cause of action against a defendant on a claim based on products liability in state court. The plaintiff contends that a space heater that he was using during the winter short-circuited, causing a fire that burned down his house. In July, the plaintiff’s case against the defendant went to trial, and the jury determined that the fire was caused by faulty wiring in the plaintiff’s home. The following September, the plaintiff filed a breach of warranty action against the defendant in federal court, properly invoking the court’s diversity jurisdiction. The defendant, after properly being served with process, files an answer with an affirmative defense of claim preclusion as his first pleading or motion. The defendant, at an appropriate time, then files a motion for summary judgment based on the assertion of claim preclusion. How should the court rule on the defendant’s motion?', 'Deny the motion, because the application of claim preclusion is a factual issue for the jury to determine.', 'Deny the motion, because the plaintiff’s breach of warranty theory is not the same cause of action as the plaintiff’s products liability claim.', 'Grant the motion, because claim preclusion applies to bar the claim.', 'Grant the motion, because the defendant, by raising the issue in his first pleading or motion, did not waive the defense of claim preclusion.', 'C', '', 'civ0025', 0, NULL),
('civ0026', 'MBE-Civil-Procedure-Sample-Test-Questions', '5', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '6', '', 'A wholesaler brought a federal diversity action against a large pharmaceutical company for breach of contract. During jury selection, one potential juror stated that five years earlier he had been an employee of the company and still owned several hundred shares of its stock. In response to questioning from the judge, the potential juror stated that he could fairly consider the evidence in the case. The wholesaler’s attorney has asked the judge to strike the potential juror for cause. Should the judge strike the potential juror for cause?', 'No, because the potential juror said that he could fairly consider the evidence in the case.', 'No, because the wholesaler’s attorney could use a peremptory challenge to strike the potential juror.', 'Yes, because other potential jurors still remain available for the jury panel.', 'Yes, because the potential juror is presumed to be biased because of his relationship to the company.', 'D', 'Stock ownership, or having worked for or having a spouse who works or worked for one of the litigants, has been found to create a presumption of bias that merits striking a potential juror for cause.', 'civ0026', 0, NULL),
('civ0027', 'MBE-Civil-Procedure-Sample-Test-Questions', '6', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '7', '', 'After being fired, a woman sued her former employer in federal court, alleging that her supervisor had discriminated against her on the basis of her sex. The woman’s complaint included a lengthy description of what the supervisor had said and done over the years, quoting his telephone calls and emails to her and her own emails to the supervisor’s manager asking for help. The employer moved for summary judgment, alleging that the woman was a pathological liar who had filed the action and included fictitious documents in revenge for having been fired. Because the woman’s attorney was at a lengthy out-of-state trial when the summary-judgment motion was filed, he failed to respond to it. The court therefore granted the motion in a one-line order and entered final judgment. The woman has appealed. Is the appellate court likely to uphold the trial court’s ruling?', 'No, because the complaint’s allegations were detailed and specific.', 'No, because the employer moved for summary judgment on the basis that the woman was not credible, creating a factual dispute.', 'Yes, because the woman’s failure to respond to the summary-judgment motion means that there was no sworn affidavit to support her allegations and supporting documents.', 'Yes, because the woman’s failure to respond to the summary-judgment motion was a default giving sufficient basis to grant the motion.', 'B', 'The standard for summary judgment is whether there is no genuine dispute as to any material fact such that the moving party is entitled to judgment as a matter of law. By challenging the woman’s credibility, the employer disputed all the facts and evidence.', 'civ0027', 0, NULL),
('civ0028', 'MBE-Civil-Procedure-Sample-Test-Questions', '7', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '8', '', 'A man brought a federal diversity action against his insurance company, alleging that the company had breached its duty under his insurance policy by refusing to pay for his medical expenses resulting from a mountain-biking accident. At the jury trial, the man presented evidence that he had paid all premiums on the insurance policy and that the policy covered personal-injury-related medical expenses arising from accidents. After he rested his case, the company presented evidence that a provision of the policy excluded payment for injury-related expenses resulting from an insured’s “unduly risky” behavior. The company also presented a witness who testified that the accident had occurred in an area where posted signs warned bikers not to enter. The man did not cross-examine the witness. After resting its case, the company moved for judgment as a matter of law. Should the court grant the motion?', 'No, because a motion for judgment as a matter of law must first be made at the close of the plaintiff’s case-in-chief.', 'No, because whether the man’s behavior was unduly risky is a question of fact for the jury to resolve.', 'Yes, because the company’s uncontradicted evidence of the man’s unduly risky behavior means that no reasonable jury could find that the policy covers his injuries.', 'Yes, because the man waived his right to rebut the company’s evidence by not addressing the “unduly risky” policy provision in his case-in-chief.', 'B', 'Whether the man’s behavior was unduly risky is a question of fact for the jury to resolve.', 'civ0028', 0, NULL),
('civ0029', 'MBE-Civil-Procedure-Sample-Test-Questions', '8', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '9', '', 'A motorcyclist was involved in a collision with a truck. The motorcyclist sued the truck driver in state court for damage to the motorcycle. The jury returned a verdict for the truck driver, and the court entered judgment. The motorcyclist then sued the company that employed the driver and owned the truck in federal court for personal-injury damages, and the company moved to dismiss based on the state-court judgment. If the court grants the company’s motion, what is the likely explanation?', 'Claim preclusion (res judicata) bars the motorcyclist’s action against the company.', 'Issue preclusion (collateral estoppel) establishes the company’s lack of negligence.', 'The motorcyclist violated the doctrine of election of remedies.', 'The state-court judgment is the law of the case.', 'A', 'Claim preclusion (res judicata) bars relitigation of claims that were or could have been raised in a prior action between the same parties or their privies based on the same cause of action.', 'civ0029', 0, NULL),
('civ0030', 'MBE-Civil-Procedure-Sample-Test-Questions', '9', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '10', '', 'A student at a private university sued the university in federal court for negligence after he fell from scaffolding in a university-owned theater building. At trial, after briefing from both parties, the court permitted the jury to hear testimony that there had been several previous accidents in the same building. The jury found for the student, and the university appealed. One of the university’s arguments on appeal is that the testimony about the previous accidents should have been excluded as irrelevant and highly prejudicial. Which standard of review applies to this argument?', 'Abuse of discretion.', 'Clearly erroneous.', 'De novo.', 'Harmless error.', 'A', 'Evidentiary rulings are reviewed for abuse of discretion.', 'civ0030', 0, NULL),
('civ0031', 'MBE-Civil-Procedure-Sample-Test-Questions', '4', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '5', '', 'A consumer from State A filed a $100,000 products liability action in federal court against a manufacturer incorporated and with its principal place of business in State B. The consumer claimed that a flaw in the manufacturer’s product had resulted in severe injuries to the consumer. In its answer, the manufacturer asserted a third-party complaint against the product designer, also incorporated and with its principal place of business in State B. Believing that the consumer had sued the wrong defendant, the manufacturer claimed both that the designer was solely responsible for the flaw that had led to the consumer’s injuries and that the manufacturer was not at fault. The designer is aware that the manufacturer did not follow all of the designer’s specifications when making the product. Which of the following arguments is most likely to achieve the designer’s goal of dismissal of the third-party complaint?', 'The court does not have subject-matter jurisdiction over the third-party complaint, because both the manufacturer and the designer are citizens of State B.', 'The manufacturer failed to obtain the court’s leave to file the third-party complaint.', 'The manufacturer’s failure to follow the designer’s specifications caused the flaw that resulted in the consumer’s injuries.', 'The manufacturer’s third-party complaint failed to state a proper third-party claim.', 'D', 'Under Federal Rule 14(a)(1), a defendant may serve a third-party claim only on a nonparty “who is or may be liable to it for all or part of the claim against it.”', 'civ0031', 0, NULL),
('civ0032', 'MBE-Civil-Procedure-Sample-Test-Questions', '1', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '2', '', 'An investor from State A filed an action against his State B stockbroker in federal court in State A. The summons and complaint were served at the stockbroker’s office in State B, where the process server handed the documents to the stockbroker’s administrative assistant. The stockbroker has answered the complaint, asserting the defense of improper service of process. Assume that both states’ requirements for service of process are identical to the requirements of the Federal Rules of Civil Procedure. Is the court likely to dismiss the action for improper service of process?', 'No, because service was made on a person of suitable age found at the stockbroker’s place of employment.', 'No, because the stockbroker waived her claim for improper service of process by asserting it in her answer.', 'Yes, because an individual defendant may not be served by delivering process to a third party found at the defendant’s place of employment.', 'Yes, because the process of State A courts is not effective in State B.', 'C', 'Federal Rule 4(e)(2) provides that an individual defendant may be served by delivering a copy of the summons and complaint to an agent authorized by appointment or by law to receive service of process on behalf of the defendant. No facts suggest that the administrative assistant was a designated agent.', 'civ0032', 0, NULL),
('civ0033', 'MBE-Civil-Procedure-Sample-Test-Questions', '2', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '3', '', 'A truck driver from State A and a bus driver from State B were involved in a collision in State B that injured the truck driver. The truck driver filed a federal diversity action in State B based on negligence, seeking $100,000 in damages from the bus driver. What law of negligence should the court apply?', 'The court should apply the federal common law of negligence.', 'The court should apply the negligence law of State A, the truck driver’s state of citizenship.', 'The court should consider the negligence law of both State A and State B and apply the law that the court believes most appropriately governs negligence in this action.', 'The court should determine which state’s negligence law a state court in State B would apply and apply that law in this action.', 'D', 'In Klaxon Co. v. Stentor Elec. Mfg. Co., 313 U.S. 487 (1941), the Court made clear that in a federal diversity action a court must look to the choice-of-law rules of the state in which it sits to determine which of two competing states’ laws should be applied to the action before it.', 'civ0033', 0, NULL),
('civ0034', 'MBE-Civil-Procedure-Sample-Test-Questions', '3', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '4', '', 'A patent holder brought a patent infringement action in federal court against a licensee of the patent. The patent holder believed that a jury would be more sympathetic to his claims than a judge, and asked his lawyer to obtain a jury trial. What should the lawyer do to secure the patent holder’s right to a jury trial?', 'File and serve a complaint that includes a jury trial demand.', 'File and serve a jury trial demand at the close of discovery.', 'File and serve a jury trial demand within 30 days after the close of the pleadings.', 'Make a jury trial demand at the initial pretrial conference.', 'A', 'Federal Rule 38(b)(1) provides specifically that a jury trial demand may be included in a pleading. Including it in a properly filed and served complaint secures the right.', 'civ0034', 0, NULL),
('civ0036', 'MBE-Civil-Procedure-Sample-Test-Questions', '0', '0', 'MBE-Civil-Procedure-Sample-Test-Questions.pdf', 'Civil Procedure', '1', '', 'An entrepreneur from State A decided to sell hot sauce to the public, labeling it “Best Hot Sauce.” A company incorporated in State B and headquartered in State C sued the entrepreneur in federal court in State C. The complaint sought $50,000 in damages and alleged that the entrepreneur’s use of the name “Best Hot Sauce” infringed the company’s federal trademark. The entrepreneur filed an answer denying the allegations, and the parties began discovery. Six months later, the entrepreneur moved to dismiss for lack of subject-matter jurisdiction. Should the court grant the entrepreneur’s motion?', 'No, because the company’s claim arises under federal law.', 'No, because the entrepreneur waived the right to challenge subject-matter jurisdiction by not raising the issue initially by motion or in the answer.', 'Yes, because although the claim arises under federal law, the amount in controversy is not satisfied.', 'Yes, because although there is diversity, the amount in controversy is not satisfied.', 'A', 'The claim asserts federal trademark infringement, and therefore it arises under federal law. Subject-matter jurisdiction is proper under 28 U.S.C. § 1331 as a general federal-question action. That statute requires no minimum amount in controversy.', 'civ0036', 0, NULL),
('idx', 'dataset', 'example_id', 'prompt_id', 'source', 'subject', 'question_number', 'prompt', 'question', 'choice_a', 'choice_b', 'choice_c', 'choice_d', 'answer', 'gold_passage', 'gold_idx', 0, NULL),
('mbe_0', 'mbe', '0', '0', 'MBE-1972-78-part2', '', '1', 'Paul, the Plaintiff in a personal injury action, called Wes as a witness to testify that Dan''s car, in which Paul had been riding. ran a red light. Wes, however, testified that Dan''s car did not run the light.', 'Paul then called Vic to testify that Dan''s car did run the light. The trial judge should rule that Vic''s testimony is', 'admissible because Paul was surprised by Wes''s testimony', 'admissible because Vic''s testimony was relevant to material issues', 'inadmissible because Paul cannot impeach his own witness', 'inadmissible because Paul is bound by the testimony of his own witness', 'B', 'Rules of evidence determine what types of evidence is admissible, and the trial court judge applies these rules to the case. Generally, to be admissible, the evidence must be relevant) and not outweighed by countervailing considerations (e.g., the evidence is unfairly prejudicial, confusing, a waste of time, privileged, or, among other reasons, based on hearsay).', 'mbe_0', 0, 'Relevancy and reasons for excluding relevant evidence'),
('mbe_1', 'mbe', '1', '0', 'MBE-1972-78-part2', '', '2', 'Paul, the Plaintiff in a personal injury action, called Wes as a witness to testify that Dan''s car, in which Paul had been riding. ran a red light. Wes, however, testified that Dan''s car did not run the light.', 'On cross-examination of Vic, Dan''s attorney asked if Vic was drunk at the time he witnessed the accident. and Vic responded, "No I have never in my life been drunk." Dan''s attorney then sought to prove by Yank that Vic was drunk on New Year''s Eve two years before the accident. The trialjudge should rule that Yank''s testimony is', 'admissible to impeach Vic by showing that he had an imperfect recollection of recent events', 'admissible to show that Vic is not the kind of person on whom one should rely for ascertaining the truth', 'inadmissible because a witness cannot be impeached by proof of specific acts of misconduct', 'inadmissible because the question of whether Vic has ever been drunk is a collateral matter', 'D', 'A matter is considered collateral if “the matter itself is not relevant in the litigation to establish a fact of consequence, i.e., not relevant for a purpose other than mere contradiction of the in-court testimony of the witness.” United States v. Beauchamp, 986 F.2d 1, 4 (1st Cir.1993) (quoting 1 McCormick on Evidence § 45 (4th ed. 1992)). Although any demonstrated inconsistency in a witness''s statement may impeach a witness''s credibility, other concerns (such as wasting time and misleading the jury) become more important when the inconsistency at *409 issue involves a statement relating to a matter that “is not relevant in the litigation to establish a fact of consequence.” Id. (quoting 1 McCormick on Evidence § 45, 169 (4th ed. 1992)).', 'mbe_1', 0, '2'),
('mbe_10', 'mbe', '10', '4', 'MBE-1972-78-part2', '', '11', 'Addle, who has been in the painting and contracting business for ten years and has a fine reputation, contracts to paint Boone''s barn. Boone''s barn is a standard red barn with loft. The contract has no provision regarding assignment.', 'If Addle assigns the contract to Coot, who has comparable experience and reputation, which of the following statements is correct?', 'Addle is in breach of contract.', 'Boone may refuse to accept performance by Coot.', 'Boone is required to accept performance by Coot.', 'There is a novation.', 'C', '“[e]xceptions to the rule that contracts are freely assignable are when the contract expressly provides that it is not assignable or when performance of some term of the contract involves an element of personal skill or credit.” Hurst v. West, 49 N.C.App. 598, 272 S.E.2d 378, 382–83 (1980) (citations omitted).', 'mbe_7', 0, '11'),
('mbe_100', 'mbe', '100', '59', 'MBE-1972-78-part3', '', '51', 'On March I, Green and Brown orally agreed that Brown would erect a boathouse on Green''s lot and dig a channel from the boathouse, across Clark''s lot, to a lake. Clark had already orally agreed with Green to permit the digging of the channel across Clark''s lot. Brown agreed to begin work on the boathouse on March 15, and to complete all the work before June 1. The total price of $10,000 was to be paid by Green in three installments: $2,500 on March 15; $2,500 when the boathouse was completed; $5,000 when Brown finished the digging of the channel.', 'Assume that Green paid the $2,500 on March 15, that Brown completed the boathouse, that Green paid the second installment of $2,500, and that Brown completed the digging of the channel but not until July 1. Assume further that the absence of a writing is not raised as a defense. Which of the following is (are) correct? I. Green has a cause of action against Brown for breach of contract. II. Green is excused from paying the $5,000.', 'I only', 'II only', 'Both I and II', 'Neither I nor II', 'A', 'Any kind of contract may be considered broken ("breached") once one party unconditionally refuses to perform under the contract as promised, regardless of when performance is supposed to take place. This unconditional refusal is known as a "repudiation" of a contract.
